DROP TABLE IF EXISTS posts;

CREATE TABLE posts (
    post_id   INTEGER PRIMARY KEY,
    body      TEXT NOT NULL,
    published BOOLEAN NOT NULL DEFAULT false
);

INSERT INTO posts (post_id, body, published)
VALUES (1, 'Welcome to the community guidelines thread.', true);

INSERT INTO posts (post_id, body, published)
VALUES (2, 'Draft: how to appeal a moderation decision.', false);

INSERT INTO posts (post_id, body, published)
VALUES (3, 'Weekly digest of reported content.', true);

INSERT INTO posts (post_id, body, published)
VALUES (4, 'Unfinished notes about spam heuristics.', false);

INSERT INTO posts (post_id, body, published)
VALUES (5, 'Announcement: new reporting button is live.', true);

INSERT INTO posts (post_id, body, published)
VALUES (6, 'Pending legal review of the takedown policy.', false);

UPDATE posts
SET published = true
WHERE post_id = 2;

UPDATE posts
SET published = false
WHERE post_id = 5;

SELECT post_id, body
FROM posts
WHERE published = true
ORDER BY post_id;

SELECT post_id, body
FROM posts
WHERE published = false
ORDER BY post_id;

SELECT
    (SELECT COUNT(*) FROM posts WHERE published = true)  AS live_posts,
    (SELECT COUNT(*) FROM posts WHERE published = false) AS hidden_posts;

UPDATE posts
SET published = false
WHERE published = true
  AND body LIKE '%takedown policy%';

SELECT post_id,
       body,
       CASE WHEN published = true THEN 'visible' ELSE 'withheld' END AS moderation_state
FROM posts
ORDER BY published DESC, post_id;

DELETE FROM posts
WHERE published = false
  AND body LIKE 'Unfinished%';

SELECT post_id, body
FROM posts
WHERE published = false
ORDER BY post_id DESC;

