CREATE TABLE tasks (
    id INTEGER PRIMARY KEY,
    description VARCHAR(100) NOT NULL,
    completed BOOLEAN NOT NULL DEFAULT false
);

INSERT INTO tasks (id, description, completed) VALUES (1, 'Draft quarterly report', false);
INSERT INTO tasks (id, description, completed) VALUES (2, 'Renew office insurance', true);
INSERT INTO tasks (id, description, completed) VALUES (3, 'Order replacement laptop', false);
INSERT INTO tasks (id, description, completed) VALUES (4, 'Archive old invoices', true);
INSERT INTO tasks (id, description, completed) VALUES (5, 'Schedule team retrospective', false);
INSERT INTO tasks (id, description, completed) VALUES (6, 'Update onboarding checklist', true);

UPDATE tasks
SET completed = true
WHERE id = 1;

UPDATE tasks
SET completed = false
WHERE id = 4;

SELECT id, description
FROM tasks
WHERE completed = false
ORDER BY id;

SELECT id, description
FROM tasks
WHERE completed = true
ORDER BY id;

CREATE VIEW pending_tasks AS
SELECT id, description
FROM tasks
WHERE completed = false;

CREATE VIEW finished_tasks AS
SELECT id, description
FROM tasks
WHERE completed = true;

SELECT COUNT(*) AS pending_count
FROM pending_tasks;

SELECT COUNT(*) AS finished_count
FROM finished_tasks;

SELECT
    (SELECT COUNT(*) FROM tasks WHERE completed = true) AS done,
    (SELECT COUNT(*) FROM tasks WHERE completed = false) AS remaining,
    COUNT(*) AS total
FROM tasks;

SELECT id,
       description,
       CASE WHEN completed = true THEN 'done' ELSE 'pending' END AS status
FROM tasks
ORDER BY completed, id;

SELECT description
FROM tasks
WHERE completed = false
  AND description LIKE 'Order%';

UPDATE tasks
SET completed = true
WHERE completed = false
  AND id IN (3, 5);

SELECT id, description
FROM tasks
WHERE completed = false
ORDER BY id;

