CREATE TABLE employee (
    employee_id INTEGER PRIMARY KEY,
    full_name   VARCHAR(100) NOT NULL,
    on_leave    BOOLEAN NOT NULL
);

INSERT INTO employee (employee_id, full_name, on_leave)
VALUES (1, 'Alice Moreau', false);

INSERT INTO employee (employee_id, full_name, on_leave)
VALUES (2, 'Bruno Keller', true);

INSERT INTO employee (employee_id, full_name, on_leave)
VALUES (3, 'Carla Nguyen', false);

INSERT INTO employee (employee_id, full_name, on_leave)
VALUES (4, 'Dmitri Sokolov', true);

INSERT INTO employee (employee_id, full_name, on_leave)
VALUES (5, 'Elena Ruiz', false);

INSERT INTO employee (employee_id, full_name, on_leave)
VALUES (6, 'Farid Haddad', false);

UPDATE employee
SET on_leave = true
WHERE employee_id = 3;

UPDATE employee
SET on_leave = false
WHERE employee_id = 2;

CREATE VIEW employee_at_work AS
SELECT employee_id, full_name
FROM employee
WHERE on_leave = false;

CREATE VIEW employee_on_leave AS
SELECT employee_id, full_name
FROM employee
WHERE on_leave = true;

SELECT employee_id, full_name, on_leave
FROM employee
WHERE on_leave = false
ORDER BY employee_id;

SELECT employee_id, full_name, on_leave
FROM employee
WHERE on_leave = true
ORDER BY employee_id;

SELECT
    (SELECT COUNT(*) FROM employee_at_work)  AS working_count,
    (SELECT COUNT(*) FROM employee_on_leave) AS leave_count;

SELECT e.employee_id,
       e.full_name,
       CASE WHEN e.on_leave = true THEN 'On leave' ELSE 'At work' END AS status_label
FROM employee e
ORDER BY e.on_leave DESC, e.employee_id;

SELECT full_name
FROM employee
WHERE on_leave = true
  AND employee_id IN (SELECT employee_id FROM employee WHERE employee_id > 3);

