CREATE TABLE bugs (
    bug_id   INTEGER PRIMARY KEY,
    title    VARCHAR(120) NOT NULL,
    is_open  BOOLEAN NOT NULL
);

INSERT INTO bugs (bug_id, title, is_open)
VALUES (1, 'Login form rejects valid passwords', true);

INSERT INTO bugs (bug_id, title, is_open)
VALUES (2, 'Export to CSV drops the last row', false);

INSERT INTO bugs (bug_id, title, is_open)
VALUES (3, 'Crash when uploading empty file', true);

INSERT INTO bugs (bug_id, title, is_open)
VALUES (4, 'Timestamps shown in wrong timezone', false);

INSERT INTO bugs (bug_id, title, is_open)
VALUES (5, 'Search ignores accented characters', false);

INSERT INTO bugs (bug_id, title, is_open)
VALUES (6, 'Memory leak in report scheduler', true);

UPDATE bugs
   SET is_open = false
 WHERE bug_id = 1;

UPDATE bugs
   SET is_open = true
 WHERE bug_id = 5;

SELECT bug_id, title
  FROM bugs
 WHERE is_open = true
 ORDER BY bug_id;

SELECT bug_id, title
  FROM bugs
 WHERE is_open = false
 ORDER BY bug_id;

CREATE VIEW open_bug_report AS
SELECT bug_id,
       title,
       'OPEN' AS status_label
  FROM bugs
 WHERE is_open = true;

CREATE VIEW closed_bug_report AS
SELECT bug_id,
       title,
       'CLOSED' AS status_label
  FROM bugs
 WHERE is_open = false;

SELECT status_label, COUNT(*) AS bug_count
  FROM (SELECT status_label FROM open_bug_report
        UNION ALL
        SELECT status_label FROM closed_bug_report) AS combined
 GROUP BY status_label
 ORDER BY status_label;

SELECT MIN(bug_id) AS oldest_unresolved
  FROM bugs
 WHERE is_open = true;

DELETE FROM bugs
 WHERE is_open = false
   AND bug_id > 5;

