DROP TABLE IF EXISTS properties;

CREATE TABLE properties (
    property_id INTEGER PRIMARY KEY,
    address     VARCHAR(120) NOT NULL,
    is_sold     BOOLEAN NOT NULL
);

INSERT INTO properties (property_id, address, is_sold)
VALUES (1, '14 Larkspur Lane, Portland', false);

INSERT INTO properties (property_id, address, is_sold)
VALUES (2, '905 Beacon Street, Boston', false);

INSERT INTO properties (property_id, address, is_sold)
VALUES (3, '27 Harbor View Road, Seattle', true);

INSERT INTO properties (property_id, address, is_sold)
VALUES (4, '4120 Mesquite Drive, Austin', false);

INSERT INTO properties (property_id, address, is_sold)
VALUES (5, '88 Cedar Hollow Court, Denver', true);

INSERT INTO properties (property_id, address, is_sold)
VALUES (6, '512 Old Mill Avenue, Nashville', true);

UPDATE properties
SET is_sold = true
WHERE property_id = 2;

UPDATE properties
SET is_sold = false
WHERE property_id = 5;

SELECT property_id, address, is_sold
FROM properties
WHERE is_sold = false
ORDER BY property_id;

SELECT property_id, address, is_sold
FROM properties
WHERE is_sold = true
ORDER BY property_id;

CREATE VIEW available_listings AS
SELECT property_id, address
FROM properties
WHERE is_sold = false;

SELECT COUNT(*) AS available_count
FROM available_listings;

SELECT
    (SELECT COUNT(*) FROM properties WHERE is_sold = true)  AS sold_count,
    (SELECT COUNT(*) FROM properties WHERE is_sold = false) AS unsold_count,
    COUNT(*) AS total_count
FROM properties;

SELECT address AS recently_relisted
FROM properties
WHERE property_id = 5
  AND is_sold = false;

SELECT address AS metro_sales
FROM properties
WHERE is_sold = true
  AND (address LIKE '%Boston%' OR address LIKE '%Seattle%')
ORDER BY address;

DELETE FROM properties
WHERE property_id = 6
  AND is_sold = true;

SELECT property_id, address, is_sold
FROM properties
ORDER BY is_sold, property_id;

