CREATE TABLE fleet_vehicles (
    vehicle_id   INTEGER PRIMARY KEY,
    model_name   VARCHAR(60) NOT NULL,
    is_available BOOLEAN NOT NULL
);

CREATE TABLE dispatch_log (
    log_id      INTEGER PRIMARY KEY,
    vehicle_id  INTEGER NOT NULL REFERENCES fleet_vehicles(vehicle_id),
    destination VARCHAR(80) NOT NULL,
    completed   BOOLEAN NOT NULL
);

INSERT INTO fleet_vehicles (vehicle_id, model_name, is_available) VALUES (1, 'Ford Transit', true);
INSERT INTO fleet_vehicles (vehicle_id, model_name, is_available) VALUES (2, 'Mercedes Sprinter', true);
INSERT INTO fleet_vehicles (vehicle_id, model_name, is_available) VALUES (3, 'Iveco Daily', false);
INSERT INTO fleet_vehicles (vehicle_id, model_name, is_available) VALUES (4, 'Renault Master', false);
INSERT INTO fleet_vehicles (vehicle_id, model_name, is_available) VALUES (5, 'Volkswagen Crafter', true);
INSERT INTO fleet_vehicles (vehicle_id, model_name, is_available) VALUES (6, 'Peugeot Boxer', false);

INSERT INTO dispatch_log (log_id, vehicle_id, destination, completed) VALUES (10, 2, 'Northgate Depot', false);
INSERT INTO dispatch_log (log_id, vehicle_id, destination, completed) VALUES (11, 4, 'Riverside Market', true);
INSERT INTO dispatch_log (log_id, vehicle_id, destination, completed) VALUES (12, 6, 'Airport Freight Hub', false);
INSERT INTO dispatch_log (log_id, vehicle_id, destination, completed) VALUES (13, 1, 'Central Warehouse', true);

UPDATE fleet_vehicles
SET is_available = false
WHERE vehicle_id = 2;

UPDATE fleet_vehicles
SET is_available = true
WHERE vehicle_id = 4;

SELECT vehicle_id, model_name, is_available
FROM fleet_vehicles
WHERE is_available = true
ORDER BY vehicle_id;

SELECT vehicle_id, model_name, is_available
FROM fleet_vehicles
WHERE is_available = false
ORDER BY vehicle_id;

UPDATE dispatch_log
SET completed = true
WHERE vehicle_id = 4
  AND completed = false;

SELECT v.vehicle_id, v.model_name, d.destination
FROM fleet_vehicles v
JOIN dispatch_log d ON d.vehicle_id = v.vehicle_id
WHERE d.completed = false
ORDER BY v.vehicle_id;

SELECT v.vehicle_id, v.model_name
FROM fleet_vehicles v
WHERE v.is_available = false
  AND NOT EXISTS (
        SELECT 1
        FROM dispatch_log d
        WHERE d.vehicle_id = v.vehicle_id
          AND d.completed = false
  )
ORDER BY v.vehicle_id;

SELECT COUNT(*) AS ready_for_dispatch
FROM fleet_vehicles
WHERE is_available = true;

