CREATE TABLE tickets (
    ticket_id   integer PRIMARY KEY,
    attendee    text NOT NULL,
    scanned     boolean NOT NULL DEFAULT false
);

INSERT INTO tickets (ticket_id, attendee, scanned) VALUES (1, 'Ana Reyes', true);

INSERT INTO tickets (ticket_id, attendee, scanned) VALUES (2, 'Bilal Khan', true);

INSERT INTO tickets (ticket_id, attendee, scanned) VALUES (3, 'Carla Mendes', false);

INSERT INTO tickets (ticket_id, attendee, scanned) VALUES (4, 'Dmitri Volkov', false);

INSERT INTO tickets (ticket_id, attendee, scanned) VALUES (5, 'Elena Costa', true);

INSERT INTO tickets (ticket_id, attendee, scanned) VALUES (6, 'Farid Haddad', false);

UPDATE tickets
   SET scanned = true
 WHERE ticket_id = 4;

UPDATE tickets
   SET scanned = false
 WHERE ticket_id = 2;

SELECT ticket_id, attendee
  FROM tickets
 WHERE scanned = true
 ORDER BY ticket_id;

SELECT ticket_id, attendee
  FROM tickets
 WHERE scanned = false
 ORDER BY ticket_id;

CREATE OR REPLACE FUNCTION scan_ticket(p_ticket_id integer)
RETURNS text AS $$
DECLARE
    v_attendee text;
BEGIN
    SELECT attendee INTO v_attendee
      FROM tickets
     WHERE ticket_id = p_ticket_id
       AND scanned = false;

    IF v_attendee IS NULL THEN
        RETURN 'rejected: unknown or already scanned ticket ' || p_ticket_id;
    END IF;

    UPDATE tickets
       SET scanned = true
     WHERE ticket_id = p_ticket_id;

    RETURN 'admitted: ' || v_attendee;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION door_summary()
RETURNS text AS $$
DECLARE
    v_in  integer;
    v_out integer;
BEGIN
    SELECT count(*) INTO v_in FROM tickets WHERE scanned = true;
    SELECT count(*) INTO v_out FROM tickets WHERE scanned = false;
    RETURN v_in || ' scanned, ' || v_out || ' still outside';
END;
$$ LANGUAGE plpgsql;

SELECT scan_ticket(3) AS gate_a,
       scan_ticket(3) AS gate_a_retry,
       scan_ticket(2) AS gate_b;

SELECT door_summary() AS door_report;

SELECT ticket_id, attendee, scanned
  FROM tickets
 ORDER BY scanned = false DESC, ticket_id;

