CREATE TABLE dining_tables (
    id            SERIAL PRIMARY KEY,
    table_number  INTEGER NOT NULL UNIQUE,
    seats         INTEGER NOT NULL CHECK (seats > 0),
    occupied      BOOLEAN NOT NULL
);

INSERT INTO dining_tables (table_number, seats, occupied) VALUES (1, 2, true);
INSERT INTO dining_tables (table_number, seats, occupied) VALUES (2, 4, false);
INSERT INTO dining_tables (table_number, seats, occupied) VALUES (3, 4, true);
INSERT INTO dining_tables (table_number, seats, occupied) VALUES (4, 6, false);
INSERT INTO dining_tables (table_number, seats, occupied) VALUES (5, 2, false);
INSERT INTO dining_tables (table_number, seats, occupied) VALUES (6, 8, true);

UPDATE dining_tables
   SET occupied = false
 WHERE table_number = 3;

UPDATE dining_tables
   SET occupied = true
 WHERE table_number = 5;

CREATE FUNCTION free_tables()
RETURNS TABLE (table_number INTEGER, seats INTEGER)
LANGUAGE sql AS $$
    SELECT d.table_number, d.seats
      FROM dining_tables d
     WHERE d.occupied = false
     ORDER BY d.seats, d.table_number;
$$;

CREATE FUNCTION busy_tables()
RETURNS TABLE (table_number INTEGER, seats INTEGER)
LANGUAGE sql AS $$
    SELECT d.table_number, d.seats
      FROM dining_tables d
     WHERE d.occupied = true
     ORDER BY d.table_number;
$$;

CREATE FUNCTION seat_party(party_size INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    chosen INTEGER;
BEGIN
    SELECT d.table_number
      INTO chosen
      FROM dining_tables d
     WHERE d.occupied = false
       AND d.seats >= party_size
     ORDER BY d.seats, d.table_number
     LIMIT 1;

    IF chosen IS NULL THEN
        RETURN NULL;
    END IF;

    UPDATE dining_tables
       SET occupied = true
     WHERE table_number = chosen;

    RETURN chosen;
END;
$$;

CREATE FUNCTION clear_table(target INTEGER)
RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE dining_tables
       SET occupied = false
     WHERE table_number = target
       AND occupied = true;

    RETURN FOUND;
END;
$$;

SELECT table_number, seats FROM dining_tables WHERE occupied = false ORDER BY table_number;
SELECT table_number, seats FROM dining_tables WHERE occupied = true ORDER BY table_number;

SELECT seat_party(4) AS seated_party_of_four;
SELECT clear_table(1) AS table_one_cleared;
SELECT * FROM free_tables();
SELECT * FROM busy_tables();

