CREATE OR REPLACE FUNCTION board_passenger(p_id integer)
RETURNS text AS $$
DECLARE
    v_name text;
BEGIN
    SELECT passenger_name INTO v_name
      FROM boarding_manifest
     WHERE passenger_id = p_id
       AND boarded = false;

    IF v_name IS NULL THEN
        RETURN format('passenger %s is unknown or already on board', p_id);
    END IF;

    UPDATE boarding_manifest
       SET boarded = true
     WHERE passenger_id = p_id;

    RETURN format('%s boarded', v_name);
END;
$$ LANGUAGE plpgsql;

