    v_on  integer;
    v_off integer;
BEGIN
    SELECT count(*) INTO v_on
      FROM boarding_manifest
     WHERE boarded = true;

    SELECT count(*) INTO v_off
      FROM boarding_manifest
     WHERE boarded = false;

    RETURN format('%s on board, %s still waiting', v_on, v_off);
END;
$$ LANGUAGE plpgsql;

