CREATE TABLE fleet (
    id serial PRIMARY KEY,
    model text NOT NULL,
    available boolean NOT NULL
);

CREATE TABLE fleet_audit (
    id serial PRIMARY KEY,
    model text NOT NULL,
    action text NOT NULL,
    new_status boolean,
    logged_at timestamptz NOT NULL DEFAULT now()
);

CREATE FUNCTION set_availability(p_model text, p_status boolean)
RETURNS integer AS $$
DECLARE
    v_count integer;
BEGIN
    UPDATE fleet
       SET available = p_status
     WHERE model = p_model
       AND available <> p_status;
    GET DIAGNOSTICS v_count = ROW_COUNT;

    INSERT INTO fleet_audit (model, action, new_status)
    VALUES (p_model, 'update', p_status);

    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION available_models()
RETURNS SETOF text AS $$
    SELECT model FROM fleet WHERE available = true ORDER BY model;
$$ LANGUAGE sql;

CREATE FUNCTION unavailable_models()
RETURNS SETOF text AS $$
    SELECT model FROM fleet WHERE available = false ORDER BY model;
$$ LANGUAGE sql;

CREATE FUNCTION run()
RETURNS TABLE (model text, available boolean) AS $$
DECLARE
    v_model text;
BEGIN
    INSERT INTO fleet (model, available) VALUES ('sedan', true);
    INSERT INTO fleet (model, available) VALUES ('minivan', false);
    INSERT INTO fleet (model, available) VALUES ('truck', false);

    PERFORM set_availability('minivan', true);
    PERFORM set_availability('sedan', false);

    FOR v_model IN SELECT * FROM available_models() LOOP
        RAISE NOTICE 'ready for rental: %', v_model;
    END LOOP;

    FOR v_model IN SELECT * FROM unavailable_models() LOOP
        RAISE NOTICE 'in the shop: %', v_model;
        INSERT INTO fleet_audit (model, action, new_status)
        VALUES (v_model, 'retire', false);
    END LOOP;

    DELETE FROM fleet WHERE available = false;

    RETURN QUERY
        SELECT f.model, f.available
          FROM fleet f
         WHERE f.available = true
         ORDER BY f.model;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM run();

