CREATE TABLE playlist_tracks (
    track_id    SERIAL PRIMARY KEY,
    song_name   VARCHAR(120) NOT NULL UNIQUE,
    downloaded  BOOLEAN NOT NULL
);

INSERT INTO playlist_tracks (song_name, downloaded)
VALUES ('Acoustic Sunrise', true);

INSERT INTO playlist_tracks (song_name, downloaded)
VALUES ('Rock Anthem', false);

INSERT INTO playlist_tracks (song_name, downloaded)
VALUES ('Jazz Midnight', false);

UPDATE playlist_tracks
SET downloaded = true
WHERE song_name = 'Rock Anthem';

UPDATE playlist_tracks
SET downloaded = false
WHERE song_name = 'Acoustic Sunrise';

CREATE OR REPLACE FUNCTION list_downloaded()
RETURNS TABLE (track_id INTEGER, song_name VARCHAR) AS $$
    SELECT t.track_id, t.song_name
    FROM playlist_tracks t
    WHERE t.downloaded = true
    ORDER BY t.track_id;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION list_pending()
RETURNS TABLE (track_id INTEGER, song_name VARCHAR) AS $$
    SELECT t.track_id, t.song_name
    FROM playlist_tracks t
    WHERE t.downloaded = false
    ORDER BY t.track_id;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION purge_pending()
RETURNS INTEGER AS $$
DECLARE
    removed INTEGER;
BEGIN
    DELETE FROM playlist_tracks
    WHERE downloaded = false;
    GET DIAGNOSTICS removed = ROW_COUNT;
    RETURN removed;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION execute()
RETURNS TEXT AS $$
DECLARE
    ready_names TEXT;
    waiting_names TEXT;
    purged INTEGER;
BEGIN
    SELECT string_agg(song_name, ', ' ORDER BY track_id)
    INTO ready_names
    FROM list_downloaded();

    SELECT string_agg(song_name, ', ' ORDER BY track_id)
    INTO waiting_names
    FROM list_pending();

    purged := purge_pending();

    RETURN format('downloaded=[%s]; pending=[%s]; purged=%s; remaining_pending=%s',
                  coalesce(ready_names, 'none'),
                  coalesce(waiting_names, 'none'),
                  purged,
                  (SELECT count(*) FROM playlist_tracks WHERE downloaded = false));
END;
$$ LANGUAGE plpgsql;

SELECT execute();

