CREATE TABLE IF NOT EXISTS digital_assets (
    asset_id    SERIAL PRIMARY KEY,
    file_name   TEXT NOT NULL UNIQUE,
    is_public   BOOLEAN NOT NULL
);

CREATE OR REPLACE FUNCTION publish_asset(p_file_name TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE digital_assets
       SET is_public = true
     WHERE file_name = p_file_name
       AND is_public = false;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION retract_asset(p_file_name TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE digital_assets
       SET is_public = false
     WHERE file_name = p_file_name
       AND is_public = true;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION asset_report()
RETURNS TABLE(file_name TEXT, visibility TEXT) AS $$
