CREATE TABLE speaker_proposals (
    proposal_id SERIAL PRIMARY KEY,
    topic VARCHAR(120) NOT NULL UNIQUE,
    accepted BOOLEAN NOT NULL
);

CREATE OR REPLACE FUNCTION submit_proposal(p_topic VARCHAR, p_accepted BOOLEAN)
RETURNS INTEGER AS $$
DECLARE
    v_id INTEGER;
BEGIN
    INSERT INTO speaker_proposals (topic, accepted)
    VALUES (p_topic, p_accepted)
    RETURNING proposal_id INTO v_id;

    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION decide_proposal(p_topic VARCHAR, p_accepted BOOLEAN)
RETURNS INTEGER AS $$
DECLARE
    v_changed INTEGER;
BEGIN
    UPDATE speaker_proposals
       SET accepted = p_accepted
     WHERE topic = p_topic
       AND accepted <> p_accepted;

    GET DIAGNOSTICS v_changed = ROW_COUNT;
    RETURN v_changed;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION report_line(p_topic VARCHAR, p_accepted BOOLEAN)
RETURNS TEXT AS $$
    SELECT p_topic || CASE WHEN p_accepted = true THEN ' -> on the schedule'
                           ELSE ' -> not selected' END;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION execute()
RETURNS TABLE (topic VARCHAR, status TEXT) AS $$
BEGIN
    PERFORM submit_proposal('artificial intelligence', true);
    PERFORM submit_proposal('legacy systems', false);
    PERFORM submit_proposal('office politics', false);

    PERFORM decide_proposal('legacy systems', true);
    PERFORM decide_proposal('artificial intelligence', false);

    RETURN QUERY
        SELECT sp.topic, report_line(sp.topic, sp.accepted)
          FROM speaker_proposals sp
         WHERE sp.accepted = true
         ORDER BY sp.topic;

    RETURN QUERY
        SELECT sp.topic, report_line(sp.topic, sp.accepted)
          FROM speaker_proposals sp
         WHERE sp.accepted = false
         ORDER BY sp.topic;

    DELETE FROM speaker_proposals
     WHERE accepted = false;
END;
$$ LANGUAGE plpgsql;

SELECT topic, status FROM execute();

SELECT topic, accepted
  FROM speaker_proposals
 WHERE accepted = true
 ORDER BY topic;

