CREATE TABLE it_assets (
    asset_id    SERIAL PRIMARY KEY,
    model       TEXT NOT NULL,
    is_assigned BOOLEAN NOT NULL
);

CREATE TABLE asset_audit (
    audit_id   SERIAL PRIMARY KEY,
    model      TEXT NOT NULL,
    action     TEXT NOT NULL,
    new_status BOOLEAN
);

CREATE OR REPLACE FUNCTION assign_asset(p_model TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE it_assets
       SET is_assigned = true
     WHERE model = p_model
       AND is_assigned = false;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO asset_audit (model, action, new_status)
    VALUES (p_model, 'assign', true);
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION release_asset(p_model TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE it_assets
       SET is_assigned = false
     WHERE model = p_model
       AND is_assigned = true;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO asset_audit (model, action, new_status)
    VALUES (p_model, 'release', false);
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION run()
RETURNS TABLE (model TEXT, is_assigned BOOLEAN) AS $$
DECLARE
    v_freed INTEGER;
BEGIN
    INSERT INTO it_assets (model, is_assigned) VALUES ('Developer Laptop', true);
    INSERT INTO it_assets (model, is_assigned) VALUES ('Marketing Laptop', false);
    INSERT INTO it_assets (model, is_assigned) VALUES ('Design Laptop', false);

    PERFORM assign_asset('Marketing Laptop');
    PERFORM release_asset('Developer Laptop');

    RAISE NOTICE 'Assigned assets:';
    FOR model, is_assigned IN
        SELECT a.model, a.is_assigned FROM it_assets a WHERE a.is_assigned = true
    LOOP
        RAISE NOTICE '  % (assigned)', model;
    END LOOP;

    RAISE NOTICE 'Unassigned assets:';
    FOR model, is_assigned IN
        SELECT a.model, a.is_assigned FROM it_assets a WHERE a.is_assigned = false
    LOOP
        RAISE NOTICE '  % (available)', model;
    END LOOP;

    DELETE FROM it_assets WHERE it_assets.is_assigned = false;
    GET DIAGNOSTICS v_freed = ROW_COUNT;
    RAISE NOTICE 'Retired % unassigned asset(s)', v_freed;

    RETURN QUERY
    SELECT a.model, a.is_assigned
      FROM it_assets a
     WHERE a.is_assigned = true
     ORDER BY a.model;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM run();

