-- Plant nursery inventory: schema, helpers and the process() driver script.

DROP TABLE IF EXISTS process_log;
DROP TABLE IF EXISTS nursery_stock;

CREATE TABLE nursery_stock (
    species      text PRIMARY KEY,
    is_perennial boolean NOT NULL
);

CREATE TABLE process_log (
    step         text    NOT NULL,
    species      text    NOT NULL,
    is_perennial boolean NOT NULL
);

CREATE OR REPLACE FUNCTION add_plant(p_species text, p_perennial boolean)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    IF p_species IS NULL OR btrim(p_species) = '' THEN
        RAISE EXCEPTION 'species name must not be empty';
    END IF;

    INSERT INTO nursery_stock (species, is_perennial)
    VALUES (btrim(p_species), p_perennial);
END;
$$;

CREATE OR REPLACE FUNCTION count_by_status(p_perennial boolean)
RETURNS bigint LANGUAGE sql AS $$
    SELECT count(*) FROM nursery_stock WHERE is_perennial = p_perennial;
$$;

CREATE OR REPLACE PROCEDURE process()
LANGUAGE plpgsql AS $$
BEGIN
    PERFORM add_plant('Rose Bush', true);
    PERFORM add_plant('Tomato Plant', false);
    PERFORM add_plant('Basil Plant', false);

    UPDATE nursery_stock
       SET is_perennial = true
     WHERE species = 'Tomato Plant';

    UPDATE nursery_stock
       SET is_perennial = false
     WHERE species = 'Rose Bush';

    INSERT INTO process_log (step, species, is_perennial)
    SELECT 'perennial-selection', species, is_perennial
      FROM nursery_stock
     WHERE is_perennial = true;

    INSERT INTO process_log (step, species, is_perennial)
    SELECT 'annual-selection', species, is_perennial
      FROM nursery_stock
     WHERE is_perennial = false;

    DELETE FROM nursery_stock
     WHERE is_perennial = false;
END;
$$;

CALL process();

SELECT species FROM process_log WHERE is_perennial = true;
SELECT species FROM process_log WHERE is_perennial = false;

SELECT count_by_status(true)  AS perennials_left,
       count_by_status(false) AS annuals_left;

