CREATE TABLE IF NOT EXISTS couriers (
    id          SERIAL PRIMARY KEY,
    driver_name TEXT NOT NULL UNIQUE,
    on_shift    BOOLEAN NOT NULL
);

CREATE TABLE IF NOT EXISTS shift_log (
    id          SERIAL PRIMARY KEY,
    driver_name TEXT NOT NULL,
    on_shift    BOOLEAN NOT NULL,
    logged_at   TIMESTAMP NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION start_shift(p_name TEXT) RETURNS VOID AS $$
    UPDATE couriers SET on_shift = true WHERE driver_name = p_name;
    INSERT INTO shift_log (driver_name, on_shift)
    SELECT driver_name, true FROM couriers WHERE driver_name = p_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION end_shift(p_name TEXT) RETURNS VOID AS $$
    UPDATE couriers SET on_shift = false WHERE driver_name = p_name;
    INSERT INTO shift_log (driver_name, on_shift)
    SELECT driver_name, false FROM couriers WHERE driver_name = p_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION roster(p_status BOOLEAN)
RETURNS TABLE (driver_name TEXT, on_shift BOOLEAN) AS $$
    SELECT c.driver_name, c.on_shift
    FROM couriers c
    WHERE c.on_shift = p_status
    ORDER BY c.driver_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION run() RETURNS TABLE (report TEXT) AS $$
DECLARE
    rec RECORD;
    removed INTEGER;
BEGIN
    DELETE FROM couriers;
    DELETE FROM shift_log;

    INSERT INTO couriers (driver_name, on_shift) VALUES ('david', true);
    INSERT INTO couriers (driver_name, on_shift) VALUES ('sarah', false);
    INSERT INTO couriers (driver_name, on_shift) VALUES ('michael', false);

    PERFORM start_shift('sarah');
    PERFORM end_shift('david');

    FOR rec IN SELECT * FROM roster(true) LOOP
        report := 'on shift: ' || rec.driver_name;
        RETURN NEXT;
    END LOOP;

    FOR rec IN SELECT * FROM roster(false) LOOP
        report := 'off shift: ' || rec.driver_name;
        RETURN NEXT;
    END LOOP;

    FOR rec IN
        SELECT driver_name, logged_at FROM shift_log
        WHERE on_shift = true
        ORDER BY logged_at
    LOOP
        report := 'clock-in logged for ' || rec.driver_name;
        RETURN NEXT;
    END LOOP;

    DELETE FROM couriers WHERE on_shift = false;
    GET DIAGNOSTICS removed = ROW_COUNT;
    report := 'released ' || removed || ' idle couriers';
    RETURN NEXT;

    SELECT count(*) INTO removed FROM couriers WHERE on_shift = true;
    report := 'remaining active couriers: ' || removed;
    RETURN NEXT;
END;
$$ LANGUAGE plpgsql;

SELECT report FROM run();

