CREATE OR REPLACE FUNCTION describe_status(flag boolean)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT CASE WHEN flag = TRUE THEN 'protected' ELSE 'deletable' END;
$$;

CREATE OR REPLACE FUNCTION instance_report()
RETURNS TABLE (server_role text, status_label text)
LANGUAGE sql
AS $$
    SELECT s.server_role, describe_status(s.is_protected)
    FROM server_instances s
    ORDER BY s.is_protected = FALSE, s.server_role;
$$;

CREATE OR REPLACE PROCEDURE process()
LANGUAGE plpgsql
AS $$
DECLARE
    rec record;
BEGIN
    INSERT INTO server_instances (server_role, is_protected)
    VALUES ('main-database', TRUE);

    INSERT INTO server_instances (server_role, is_protected)
    VALUES ('test-server', FALSE);

    INSERT INTO server_instances (server_role, is_protected)
    VALUES ('cache-node', FALSE);

    UPDATE server_instances
       SET is_protected = TRUE
     WHERE server_role = 'test-server';

    UPDATE server_instances
       SET is_protected = FALSE
     WHERE server_role = 'main-database';

    FOR rec IN
        SELECT server_role FROM server_instances WHERE is_protected = TRUE
    LOOP
        RAISE NOTICE 'keeping %', rec.server_role;
    END LOOP;

    FOR rec IN
        SELECT server_role FROM server_instances WHERE is_protected = FALSE
    LOOP
        RAISE NOTICE 'purging %', rec.server_role;
    END LOOP;

    DELETE FROM server_instances
     WHERE is_protected = FALSE;
END;
$$;

CALL process();

SELECT server_role, status_label FROM instance_report();

SELECT count(*) AS survivors
  FROM server_instances
 WHERE is_protected = TRUE;

