DROP TABLE IF EXISTS volunteer_shifts;

CREATE TABLE volunteer_shifts (
    person_name text PRIMARY KEY,
    trained     boolean NOT NULL
);

CREATE OR REPLACE FUNCTION signup(p_name text, p_trained boolean)
RETURNS void AS $$
BEGIN
    IF p_name IS NULL OR btrim(p_name) = '' THEN
        RAISE EXCEPTION 'volunteer name must not be blank';
    END IF;
    INSERT INTO volunteer_shifts (person_name, trained)
    VALUES (btrim(p_name), coalesce(p_trained, false));
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mark_trained(p_name text, p_trained boolean)
RETURNS integer AS $$
DECLARE
    v_changed integer;
BEGIN
    UPDATE volunteer_shifts
       SET trained = p_trained
     WHERE person_name = p_name
       AND trained IS DISTINCT FROM p_trained;
    GET DIAGNOSTICS v_changed = ROW_COUNT;
    RETURN v_changed;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION roster(p_trained boolean)
RETURNS TABLE (person_name text, trained boolean) AS $$
    SELECT person_name, trained
      FROM volunteer_shifts
     WHERE trained = p_trained
     ORDER BY person_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION drop_untrained()
RETURNS integer AS $$
DECLARE
    v_removed integer;
BEGIN
    DELETE FROM volunteer_shifts WHERE trained = false;
    GET DIAGNOSTICS v_removed = ROW_COUNT;
    RETURN v_removed;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION execute()
RETURNS TABLE (stage text, person_name text, trained boolean) AS $$
BEGIN
    PERFORM signup('anna', true);
    PERFORM signup('ben', false);
    PERFORM signup('chris', false);

    PERFORM mark_trained('ben', true);
    PERFORM mark_trained('anna', false);

    RETURN QUERY
    SELECT 'trained'::text, r.person_name, r.trained FROM roster(true) AS r;

    RETURN QUERY
    SELECT 'untrained'::text, r.person_name, r.trained FROM roster(false) AS r;

    RETURN QUERY
    SELECT 'removed'::text, v.person_name, v.trained
      FROM volunteer_shifts v
     WHERE v.trained = false;

    PERFORM drop_untrained();

    RETURN QUERY
    SELECT 'remaining'::text, v.person_name, v.trained
      FROM volunteer_shifts v
     ORDER BY v.person_name;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM execute();

