-- Cinema screenings management (PostgreSQL / plpgsql)

DROP TABLE IF EXISTS screenings;
CREATE TABLE screenings (
    id            serial PRIMARY KEY,
    title         text NOT NULL,
    has_subtitles boolean NOT NULL
);

DROP FUNCTION IF EXISTS run();
DROP FUNCTION IF EXISTS set_subtitles(text, boolean);
DROP FUNCTION IF EXISTS subtitled_screenings();
DROP FUNCTION IF EXISTS unsubtitled_screenings();
DROP FUNCTION IF EXISTS purge_unsubtitled();

CREATE FUNCTION set_subtitles(p_title text, p_flag boolean) RETURNS integer AS $$
DECLARE
    v_changed integer;
BEGIN
    UPDATE screenings
       SET has_subtitles = p_flag
     WHERE title = p_title;
    GET DIAGNOSTICS v_changed = ROW_COUNT;
    RETURN v_changed;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION subtitled_screenings() RETURNS TABLE(title text, has_subtitles boolean) AS $$
    SELECT s.title, s.has_subtitles
      FROM screenings s
     WHERE s.has_subtitles = true
     ORDER BY s.title;
$$ LANGUAGE sql;

CREATE FUNCTION unsubtitled_screenings() RETURNS TABLE(title text, has_subtitles boolean) AS $$
    SELECT s.title, s.has_subtitles
      FROM screenings s
     WHERE s.has_subtitles = false
     ORDER BY s.title;
$$ LANGUAGE sql;

CREATE FUNCTION purge_unsubtitled() RETURNS integer AS $$
DECLARE
    v_removed integer;
BEGIN
    DELETE FROM screenings
     WHERE has_subtitles = false;
    GET DIAGNOSTICS v_removed = ROW_COUNT;
    RETURN v_removed;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION run() RETURNS TABLE(section text, title text, has_subtitles boolean) AS $$
DECLARE
    v_removed integer;
BEGIN
    TRUNCATE screenings RESTART IDENTITY;

    INSERT INTO screenings (title, has_subtitles)
         VALUES ('Le Ballon Rouge', true);
    INSERT INTO screenings (title, has_subtitles)
         VALUES ('Midnight Pursuit', false);
    INSERT INTO screenings (title, has_subtitles)
         VALUES ('Stand-Up Spectacular', false);

    PERFORM set_subtitles('Midnight Pursuit', true);
    PERFORM set_subtitles('Le Ballon Rouge', false);

    RETURN QUERY SELECT 'subtitled'::text, t.title, t.has_subtitles
                   FROM subtitled_screenings() t;
    RETURN QUERY SELECT 'not subtitled'::text, t.title, t.has_subtitles
                   FROM unsubtitled_screenings() t;

    v_removed := purge_unsubtitled();
    RAISE NOTICE 'screenings removed: %', v_removed;

    RETURN QUERY SELECT 'remaining'::text, s.title, s.has_subtitles
                   FROM screenings s
                  WHERE s.has_subtitles = true
                  ORDER BY s.title;
END;
$$ LANGUAGE plpgsql;

SELECT section, title, has_subtitles FROM run();

