DROP TABLE IF EXISTS exhibits;

CREATE TABLE exhibits (
    exhibit_id   SERIAL PRIMARY KEY,
    exhibit_name TEXT NOT NULL UNIQUE,
    is_interactive BOOLEAN NOT NULL,
    last_reviewed  DATE
);

CREATE OR REPLACE FUNCTION add_exhibit(p_name TEXT, p_interactive BOOLEAN)
RETURNS INTEGER AS $$
DECLARE
    v_id INTEGER;
BEGIN
    INSERT INTO exhibits (exhibit_name, is_interactive, last_reviewed)
    VALUES (p_name, p_interactive, CURRENT_DATE)
    RETURNING exhibit_id INTO v_id;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION set_interactive(p_name TEXT, p_interactive BOOLEAN)
RETURNS BOOLEAN AS $$
DECLARE
    v_changed BOOLEAN;
BEGIN
    UPDATE exhibits
       SET is_interactive = p_interactive,
           last_reviewed  = CURRENT_DATE
     WHERE exhibit_name = p_name
       AND is_interactive <> p_interactive;
    v_changed := FOUND;
    RETURN v_changed;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION exhibit_report(p_interactive BOOLEAN)
RETURNS TABLE (exhibit_name TEXT, label TEXT) AS $$
    SELECT e.exhibit_name,
           CASE WHEN e.is_interactive = true THEN 'hands-on' ELSE 'display only' END
      FROM exhibits e
     WHERE e.is_interactive = p_interactive
     ORDER BY e.exhibit_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION execute()
RETURNS TABLE (exhibit_name TEXT, label TEXT) AS $$
DECLARE
    v_science_id INTEGER;
BEGIN
    v_science_id := add_exhibit('science lab', true);
    PERFORM add_exhibit('ancient pottery', false);
    PERFORM add_exhibit('renaissance paintings', false);

    IF NOT set_interactive('ancient pottery', true) THEN
        RAISE EXCEPTION 'ancient pottery flag was already true';
    END IF;

    UPDATE exhibits
       SET is_interactive = false,
           last_reviewed  = CURRENT_DATE
     WHERE exhibit_id = v_science_id
       AND is_interactive = true;

    CREATE TEMP TABLE interactive_snapshot AS
    SELECT * FROM exhibit_report(true);

    CREATE TEMP TABLE passive_snapshot AS
    SELECT * FROM exhibit_report(false);

    DELETE FROM exhibits WHERE is_interactive = false;

    RETURN QUERY
    SELECT s.exhibit_name, s.label FROM interactive_snapshot s
    UNION ALL
    SELECT p.exhibit_name, p.label FROM passive_snapshot p;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM execute();

