DROP TABLE IF EXISTS zoo_enclosure CASCADE;

CREATE TABLE zoo_enclosure (
    habitat_name    text PRIMARY KEY,
    needs_cleaning  boolean NOT NULL
);

CREATE OR REPLACE FUNCTION add_enclosure(p_habitat text, p_needs_cleaning boolean)
RETURNS void AS $$
BEGIN
    IF p_habitat IS NULL OR btrim(p_habitat) = '' THEN
        RAISE EXCEPTION 'habitat name must not be empty';
    END IF;
    INSERT INTO zoo_enclosure (habitat_name, needs_cleaning)
    VALUES (btrim(p_habitat), p_needs_cleaning);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mark_for_cleaning(p_habitat text)
RETURNS void AS $$
BEGIN
    UPDATE zoo_enclosure
       SET needs_cleaning = true
     WHERE habitat_name = p_habitat;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mark_cleaned(p_habitat text)
RETURNS void AS $$
BEGIN
    UPDATE zoo_enclosure
       SET needs_cleaning = false
     WHERE habitat_name = p_habitat;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION list_dirty()
RETURNS SETOF zoo_enclosure AS $$
    SELECT * FROM zoo_enclosure WHERE needs_cleaning = true ORDER BY habitat_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION list_clean()
RETURNS SETOF zoo_enclosure AS $$
    SELECT * FROM zoo_enclosure WHERE needs_cleaning = false ORDER BY habitat_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION purge_clean_enclosures()
RETURNS bigint AS $$
DECLARE
    v_removed bigint;
BEGIN
    DELETE FROM zoo_enclosure WHERE needs_cleaning = false;
    GET DIAGNOSTICS v_removed = ROW_COUNT;
    RETURN v_removed;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION execute()
RETURNS TABLE (stage text, habitat text, flag boolean) AS $$
BEGIN
    PERFORM add_enclosure('Monkey Enclosure', true);
    PERFORM add_enclosure('Lion Den', false);
    PERFORM add_enclosure('Reptile House', false);

    PERFORM mark_for_cleaning('Lion Den');
    PERFORM mark_cleaned('Monkey Enclosure');

    RETURN QUERY SELECT 'needs cleaning', d.habitat_name, d.needs_cleaning FROM list_dirty() d;
    RETURN QUERY SELECT 'already clean', c.habitat_name, c.needs_cleaning FROM list_clean() c;

    RAISE NOTICE 'removed % clean enclosure(s)', purge_clean_enclosures();

    RETURN QUERY
        SELECT 'remaining', e.habitat_name, e.needs_cleaning
          FROM zoo_enclosure e
         ORDER BY e.habitat_name;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM execute();

