CREATE TABLE IF NOT EXISTS freight_cars (
    car_id      TEXT PRIMARY KEY,
    hazardous   BOOLEAN NOT NULL
);

CREATE OR REPLACE FUNCTION add_car(p_car_id TEXT, p_hazardous BOOLEAN)
RETURNS VOID AS $$
    INSERT INTO freight_cars (car_id, hazardous)
    VALUES (p_car_id, p_hazardous);
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION set_hazardous(p_car_id TEXT, p_hazardous BOOLEAN)
RETURNS VOID AS $$
    UPDATE freight_cars
       SET hazardous = p_hazardous
     WHERE car_id = p_car_id;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION list_by_status(p_hazardous BOOLEAN)
RETURNS TABLE (car_id TEXT, hazardous BOOLEAN) AS $$
    SELECT car_id, hazardous
      FROM freight_cars
     WHERE hazardous = p_hazardous
     ORDER BY car_id;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION run()
RETURNS TABLE (report_line TEXT) AS $$
DECLARE
    rec         RECORD;
    removed     INTEGER;
BEGIN
    PERFORM add_car('chemical-car', true);
    PERFORM add_car('lumber-car', false);
    PERFORM add_car('grain-car', false);

    PERFORM set_hazardous('lumber-car', true);
    PERFORM set_hazardous('chemical-car', false);

    FOR rec IN SELECT car_id FROM list_by_status(true) LOOP
        RETURN QUERY SELECT 'hazardous: ' || rec.car_id;
    END LOOP;

    FOR rec IN SELECT car_id FROM list_by_status(false) LOOP
        RETURN QUERY SELECT 'safe: ' || rec.car_id;
    END LOOP;

    DELETE FROM freight_cars
     WHERE hazardous = false;
    GET DIAGNOSTICS removed = ROW_COUNT;
    RETURN QUERY SELECT 'released ' || removed || ' non-hazardous cars';

    SELECT count(*) INTO removed
      FROM freight_cars
     WHERE hazardous = true;
    RETURN QUERY SELECT 'remaining hazardous cars: ' || removed;
END;
$$ LANGUAGE plpgsql;

SELECT report_line FROM run();

SELECT car_id, hazardous
  FROM freight_cars
 WHERE hazardous = true
 ORDER BY car_id;

