    PERFORM add_car('lumber-car', FALSE);
    PERFORM add_car('grain-car', FALSE);

    PERFORM set_hazardous('lumber-car', TRUE);
    PERFORM set_hazardous('chemical-car', FALSE);

    FOR rec IN SELECT car_id FROM list_by_status(TRUE) LOOP
        RETURN QUERY SELECT 'hazardous: ' || rec.car_id;
    END LOOP;

    FOR rec IN SELECT car_id FROM list_by_status(FALSE) LOOP
        RETURN QUERY SELECT 'safe: ' || rec.car_id;
    END LOOP;

    DELETE FROM freight_cars
     WHERE hazardous = FALSE;
    GET DIAGNOSTICS removed = ROW_COUNT;
    RETURN QUERY SELECT 'released ' || removed || ' non-hazardous cars';

    SELECT count(*) INTO removed
      FROM freight_cars
     WHERE hazardous = TRUE;
    RETURN QUERY SELECT 'remaining hazardous cars: ' || removed;
END;
$$ LANGUAGE plpgsql;

SELECT report_line FROM run();

SELECT car_id, hazardous
  FROM freight_cars
 WHERE hazardous = TRUE
 ORDER BY car_id;

