CREATE TABLE IF NOT EXISTS voter_roll (
    citizen_name text PRIMARY KEY,
    is_active    boolean NOT NULL
);

CREATE OR REPLACE FUNCTION register_citizen(p_name text, p_active boolean)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    IF p_name IS NULL OR btrim(p_name) = '' THEN
        RAISE EXCEPTION 'citizen name must not be empty';
    END IF;
    INSERT INTO voter_roll (citizen_name, is_active)
    VALUES (btrim(p_name), p_active);
END;
$$;

CREATE OR REPLACE FUNCTION set_status(p_name text, p_active boolean)
RETURNS boolean LANGUAGE plpgsql AS $$
BEGIN
    UPDATE voter_roll SET is_active = p_active WHERE citizen_name = p_name;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION count_by_status(p_active boolean)
RETURNS bigint LANGUAGE sql AS $$
    SELECT count(*) FROM voter_roll WHERE is_active = p_active;
$$;

CREATE OR REPLACE FUNCTION process()
RETURNS setof text LANGUAGE plpgsql AS $$
DECLARE
    r       record;
    purged  bigint;
BEGIN
    DELETE FROM voter_roll;

    PERFORM register_citizen('alice', true);
    PERFORM register_citizen('bob', false);
    PERFORM register_citizen('carol', false);

    IF NOT set_status('bob', true) THEN
        RAISE EXCEPTION 'bob is not on the roll';
    END IF;
    IF NOT set_status('alice', false) THEN
        RAISE EXCEPTION 'alice is not on the roll';
    END IF;

    RETURN NEXT format('active registrations: %s', count_by_status(true));
    FOR r IN
        SELECT citizen_name FROM voter_roll WHERE is_active = true
        ORDER BY citizen_name
    LOOP
        RETURN NEXT format('  active   -> %s', r.citizen_name);
    END LOOP;

    RETURN NEXT format('inactive registrations: %s', count_by_status(false));
    FOR r IN
        SELECT citizen_name FROM voter_roll WHERE is_active = false
        ORDER BY citizen_name
    LOOP
        RETURN NEXT format('  inactive -> %s', r.citizen_name);
    END LOOP;

    DELETE FROM voter_roll WHERE is_active = false;
    GET DIAGNOSTICS purged = ROW_COUNT;
    RETURN NEXT format('purged %s inactive record(s)', purged);
END;
$$;

SELECT line FROM process() AS line;

