DROP TABLE IF EXISTS pothole_reports;

CREATE TABLE pothole_reports (
    report_id    serial PRIMARY KEY,
    street_name  text    NOT NULL,
    is_repaired  boolean NOT NULL DEFAULT false
);

CREATE OR REPLACE FUNCTION add_report(p_street text, p_repaired boolean)
RETURNS integer AS $$
DECLARE
    v_id integer;
BEGIN
    IF p_street IS NULL OR btrim(p_street) = '' THEN
        RAISE EXCEPTION 'street name must not be empty';
    END IF;

    INSERT INTO pothole_reports (street_name, is_repaired)
    VALUES (btrim(p_street), p_repaired)
    RETURNING report_id INTO v_id;

    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION set_repaired(p_street text, p_flag boolean)
RETURNS integer AS $$
DECLARE
    v_rows integer;
BEGIN
    UPDATE pothole_reports
       SET is_repaired = p_flag
     WHERE street_name = btrim(p_street);

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN v_rows;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pending_count()
RETURNS bigint AS $$
    SELECT count(*) FROM pothole_reports WHERE is_repaired = false;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION execute()
RETURNS TABLE (phase text, street_name text, is_repaired boolean) AS $$
DECLARE
    v_deleted integer;
BEGIN
    PERFORM add_report('Main Street', true);
    PERFORM add_report('Oak Avenue', false);
    PERFORM add_report('Pine Lane', false);

    PERFORM set_repaired('Oak Avenue', true);
    PERFORM set_repaired('Main Street', false);

    RETURN QUERY
        SELECT 'repaired'::text, p.street_name, p.is_repaired
          FROM pothole_reports p
         WHERE p.is_repaired = true
         ORDER BY p.street_name;

    RETURN QUERY
        SELECT 'outstanding'::text, p.street_name, p.is_repaired
          FROM pothole_reports p
         WHERE p.is_repaired = false
         ORDER BY p.street_name;

    RAISE NOTICE 'purging % outstanding report(s)', pending_count();

    DELETE FROM pothole_reports WHERE is_repaired = false;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RAISE NOTICE 'removed % row(s)', v_deleted;
END;
$$ LANGUAGE plpgsql;

SELECT phase, street_name, is_repaired FROM execute();
SELECT report_id, street_name, is_repaired FROM pothole_reports ORDER BY report_id;

