CREATE TABLE IF NOT EXISTS daily_orders (
    order_id     SERIAL PRIMARY KEY,
    customer     TEXT NOT NULL,
    item         TEXT NOT NULL DEFAULT 'croissant',
    quantity     INTEGER NOT NULL DEFAULT 1,
    paid         BOOLEAN NOT NULL
);

CREATE TABLE IF NOT EXISTS order_audit (
    audit_id     SERIAL PRIMARY KEY,
    customer     TEXT NOT NULL,
    action       TEXT NOT NULL,
    paid_after   BOOLEAN NOT NULL,
    logged_at    TIMESTAMP NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION log_action(p_customer TEXT, p_action TEXT, p_paid BOOLEAN)
RETURNS VOID AS $$
    INSERT INTO order_audit (customer, action, paid_after)
    VALUES (p_customer, p_action, p_paid);
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION settle(p_customer TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE daily_orders
       SET paid = true
     WHERE customer = p_customer
       AND paid = false;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    PERFORM log_action(p_customer, 'settled', true);
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION reopen(p_customer TEXT)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE daily_orders
       SET paid = false
     WHERE customer = p_customer
       AND paid = true;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    PERFORM log_action(p_customer, 'reopened', false);
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION run()
RETURNS TABLE (customer TEXT, item TEXT, quantity INTEGER, paid BOOLEAN) AS $$
BEGIN
    INSERT INTO daily_orders (customer, item, quantity, paid)
    VALUES ('emma', 'sourdough loaf', 2, true);

    INSERT INTO daily_orders (customer, item, quantity, paid)
    VALUES ('liam', 'baguette', 3, false);

    INSERT INTO daily_orders (customer, item, quantity, paid)
    VALUES ('noah', 'cinnamon roll', 6, false);

    PERFORM settle('liam');
    PERFORM reopen('emma');

    RAISE NOTICE 'settled orders: %', (SELECT count(*) FROM daily_orders WHERE paid = true);
    RAISE NOTICE 'open orders: %', (SELECT count(*) FROM daily_orders WHERE paid = false);

    RETURN QUERY
    SELECT d.customer, d.item, d.quantity, d.paid
      FROM daily_orders d
     WHERE d.paid = true
     ORDER BY d.customer;

    RETURN QUERY
    SELECT d.customer, d.item, d.quantity, d.paid
      FROM daily_orders d
     WHERE d.paid = false
     ORDER BY d.customer;

    DELETE FROM daily_orders
     WHERE paid = false;

    RETURN;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM run();
SELECT customer, action, paid_after FROM order_audit ORDER BY audit_id;
SELECT customer, item FROM daily_orders WHERE paid = true ORDER BY customer;

