CREATE TABLE streetlights (
    id          SERIAL PRIMARY KEY,
    pole_code   TEXT NOT NULL UNIQUE,
    zone        TEXT NOT NULL,
    is_powered  BOOLEAN NOT NULL,
    is_broken   BOOLEAN NOT NULL
);

INSERT INTO streetlights (pole_code, zone, is_powered, is_broken) VALUES
    ('SL-0001', 'Harbour District', true, false),
    ('SL-0002', 'Harbour District', true, true),
    ('SL-0003', 'Old Town', false, false),
    ('SL-0004', 'Industrial Park', false, true),
    ('SL-0005', 'University Campus', true, false);

UPDATE streetlights
   SET is_powered = false
 WHERE is_broken = true;

UPDATE streetlights
   SET is_powered = true
 WHERE is_broken = false;

SELECT pole_code, zone
  FROM streetlights
 WHERE is_powered = true
 ORDER BY pole_code;

SELECT pole_code, zone
  FROM streetlights
 WHERE is_powered = false
 ORDER BY pole_code;

SELECT pole_code, zone
  FROM streetlights
 WHERE is_broken = true
 ORDER BY pole_code;

CREATE VIEW zone_health AS
SELECT zone,
       COUNT(*) AS total_poles,
       COUNT(*) FILTER (WHERE is_broken = true)  AS broken_poles,
       COUNT(*) FILTER (WHERE is_powered = true) AS lit_poles
  FROM streetlights
 GROUP BY zone;

CREATE FUNCTION report_outage(p_pole_code TEXT) RETURNS BOOLEAN AS $$
BEGIN
    UPDATE streetlights
       SET is_broken = true,
           is_powered = false
     WHERE pole_code = p_pole_code
       AND is_broken = false;
    RETURN FOUND;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION complete_repair(p_pole_code TEXT) RETURNS VOID AS $$
BEGIN
    UPDATE streetlights
       SET is_broken = false,
           is_powered = true
     WHERE pole_code = p_pole_code;
END;
$$ LANGUAGE plpgsql;

SELECT report_outage('SL-0005') AS outage_recorded;

SELECT complete_repair('SL-0004');

SELECT zone, total_poles, broken_poles, lit_poles
  FROM zone_health
 ORDER BY broken_poles DESC, zone;

SELECT pole_code, zone
  FROM streetlights
 WHERE is_powered = false
   AND is_broken = false
 ORDER BY pole_code;

