    transaction_id   integer PRIMARY KEY,
    amount           numeric(12,2) NOT NULL,
    is_cleared       boolean NOT NULL,
    is_recurring     boolean NOT NULL,
    is_tax_deductible boolean NOT NULL,
    is_business_expense boolean NOT NULL
);

