    (5, 3200.00, true,  true,  false, true);

CREATE FUNCTION audit(transaction integer) RETURNS boolean AS $$
DECLARE
    verified boolean;
BEGIN
    UPDATE budget_transactions
       SET is_business_expense = true
     WHERE transaction_id = transaction
       AND amount > 1000
       AND is_business_expense = false;

    UPDATE budget_transactions
       SET is_tax_deductible = true
     WHERE transaction_id = transaction
       AND is_business_expense = true;

    UPDATE budget_transactions
       SET is_recurring = false
     WHERE transaction_id = transaction
       AND is_cleared = false;

    SELECT is_cleared AND is_tax_deductible
      INTO verified
      FROM budget_transactions
     WHERE transaction_id = transaction;

    IF verified IS NULL THEN
        RETURN false;
    END IF;

    RETURN verified;
END;
$$ LANGUAGE plpgsql;

