CREATE OR REPLACE FUNCTION examine(animal integer)
RETURNS boolean AS $$
DECLARE
    result boolean;
BEGIN
    UPDATE livestock
       SET sick = true
     WHERE animal_id = animal
       AND body_weight < 50.00;

    UPDATE livestock
       SET isolated = true
     WHERE animal_id = animal
       AND sick = true;

    UPDATE livestock
       SET vaccinated = false
     WHERE animal_id = animal
       AND isolated = true;

    SELECT sick = false
           AND vaccinated = true
      INTO result
