    schedule_id        integer PRIMARY KEY,
    target_temperature numeric(4,1) NOT NULL,
    weekend_mode       boolean NOT NULL,
    energy_saver       boolean NOT NULL,
    heating_active     boolean NOT NULL,
    cooling_active     boolean NOT NULL
);

INSERT INTO commercial_schedules
    (schedule_id, target_temperature, weekend_mode, energy_saver, heating_active, cooling_active)
VALUES (1, 21.5, false,
              false,
              true,
              false);

INSERT INTO commercial_schedules
    (schedule_id, target_temperature, weekend_mode, energy_saver, heating_active, cooling_active)
VALUES (2, 12.0, true,
              false,
              true,
              true);

INSERT INTO commercial_schedules
    (schedule_id, target_temperature, weekend_mode, energy_saver, heating_active, cooling_active)
VALUES (3, 24.0, true,
              false,
              false,
              true);

