    (schedule_id, target_temperature, weekend_mode, energy_saver, heating_active, cooling_active)
VALUES (4, 14.5, false,
              true,
              true,
              false);

CREATE OR REPLACE FUNCTION adjust(schedule integer) RETURNS boolean AS $$
DECLARE
    rec commercial_schedules;
BEGIN
    SELECT * INTO rec FROM commercial_schedules WHERE schedule_id = schedule;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown schedule %', schedule;
    END IF;

    IF rec.target_temperature < 16.0 THEN
        UPDATE commercial_schedules
           SET heating_active = false
         WHERE schedule_id = schedule;
    END IF;

    IF rec.weekend_mode THEN
        UPDATE commercial_schedules
           SET energy_saver = true,
               cooling_active = false
         WHERE schedule_id = schedule;
    END IF;

    RETURN EXISTS (
        SELECT 1
          FROM commercial_schedules
         WHERE schedule_id = schedule
           AND (heating_active = true
                OR cooling_active = true)
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION idle_schedules() RETURNS SETOF integer AS $$
    SELECT schedule_id
      FROM commercial_schedules
     WHERE heating_active = false
       AND cooling_active = false
     ORDER BY schedule_id;
$$ LANGUAGE sql;

DO $$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT schedule_id FROM commercial_schedules ORDER BY schedule_id LOOP
        RAISE NOTICE 'schedule % regulating: %', r.schedule_id, adjust(r.schedule_id);
    END LOOP;
    RAISE NOTICE 'idle schedules: %', (SELECT array_agg(s) FROM idle_schedules() AS s);
END $$;

SELECT schedule_id, target_temperature, heating_active, cooling_active
  FROM commercial_schedules
 WHERE weekend_mode = false
   AND energy_saver = true
 ORDER BY schedule_id;

