CREATE TABLE auction_bids (
    bid_id      integer PRIMARY KEY,
    bid_amount  numeric(12,2) NOT NULL,
    reserve_met boolean NOT NULL,
    proxy_bid   boolean NOT NULL,
    winning     boolean NOT NULL,
    paid        boolean NOT NULL
);

INSERT INTO auction_bids (bid_id, bid_amount, reserve_met, proxy_bid, winning, paid) VALUES
    (1,  450.00, true,  false, true,  true),
    (2,   80.00, true,  false, true,  true),
    (3,  620.00, true,  true,  true,  true),
    (4,  310.00, false, false, false, true),
    (5,  975.00, true,  true,  false, false);

CREATE OR REPLACE FUNCTION minimum_bid() RETURNS numeric AS $$
    SELECT 100.00::numeric;
$$ LANGUAGE sql IMMUTABLE;

CREATE OR REPLACE FUNCTION process(bid integer) RETURNS boolean AS $$
DECLARE
    successful boolean;
BEGIN
    UPDATE auction_bids
       SET reserve_met = false
     WHERE bid_id = bid
       AND bid_amount < minimum_bid();

    UPDATE auction_bids
       SET winning = false
     WHERE bid_id = bid
       AND reserve_met = false;

    UPDATE auction_bids
       SET paid = false
     WHERE bid_id = bid
       AND proxy_bid = true;

    SELECT reserve_met AND winning
      INTO successful
      FROM auction_bids
     WHERE bid_id = bid;

    RETURN coalesce(successful, false);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION settle_open_bids() RETURNS integer AS $$
DECLARE
    b      integer;
    closed integer := 0;
BEGIN
    FOR b IN SELECT bid_id FROM auction_bids ORDER BY bid_id LOOP
        IF process(b) = false THEN
            closed := closed + 1;
        END IF;
    END LOOP;
    RETURN closed;
END;
$$ LANGUAGE plpgsql;

SELECT bid_id, process(bid_id) AS successful
  FROM auction_bids
 ORDER BY bid_id;

SELECT settle_open_bids() AS unsuccessful_bids;

SELECT bid_id, bid_amount, reserve_met, winning
  FROM auction_bids
 WHERE proxy_bid = false
   AND paid = true
 ORDER BY bid_id;

