CREATE OR REPLACE FUNCTION process(item integer) RETURNS boolean AS $$
DECLARE
    resolved boolean;
BEGIN
    UPDATE retail_returns
       SET refunded = FALSE,
           restocked = FALSE
     WHERE return_id = item
       AND item_received = FALSE;

    UPDATE retail_returns
       SET restocked = FALSE
     WHERE return_id = item
       AND damaged = TRUE;

    UPDATE retail_returns
       SET item_received = TRUE
     WHERE return_id = item
       AND refunded = TRUE;

    SELECT EXISTS (
               SELECT 1
                 FROM retail_returns
                WHERE return_id = item
                  AND refunded = TRUE
                  AND restocked = TRUE
           )
      INTO resolved;

    RETURN resolved;
END;
$$ LANGUAGE plpgsql;

DO $$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT return_id FROM retail_returns ORDER BY return_id LOOP
        INSERT INTO return_audit (return_id, resolved)
        VALUES (r.return_id, process(r.return_id));
    END LOOP;
END;
$$;

SELECT return_id
  FROM return_audit
 WHERE resolved = FALSE
 ORDER BY return_id;

SELECT return_id, refund_amount, item_received, restocked
  FROM retail_returns
 WHERE damaged = TRUE
   AND refunded = TRUE
 ORDER BY return_id;

