create function register(booking integer) returns boolean as $$
declare
    ready boolean;
begin
    if not exists (select 1 from tee_times where tee_time_id = booking) then
        return false;
    end if;

    update tee_times
       set carts_rented = true
     where tee_time_id = booking
       and group_size >= 4;

    update tee_times
       set fee_paid = true
     where tee_time_id = booking
       and members_only = true;

