CREATE TABLE survey_responses (
    response_id      integer PRIMARY KEY,
    completion_time  integer NOT NULL,
    consent_given    boolean NOT NULL,
    fully_completed  boolean NOT NULL,
    newsletter_optin boolean NOT NULL,
    contact_allowed  boolean NOT NULL
);

INSERT INTO survey_responses VALUES (1, 420, true, true, true, false);
INSERT INTO survey_responses VALUES (2, 12, true, true, true, true);
INSERT INTO survey_responses VALUES (3, 310, false, true, true, true);
INSERT INTO survey_responses VALUES (4, 8, false, false, true, false);
INSERT INTO survey_responses VALUES (5, 260, true, false, false, false);

CREATE FUNCTION tabulate(response integer) RETURNS boolean AS $$
DECLARE
    verdict boolean;
BEGIN
    UPDATE survey_responses
       SET fully_completed = false
     WHERE response_id = response
       AND completion_time < 30
       AND fully_completed = true;

    UPDATE survey_responses
       SET contact_allowed = false,
           newsletter_optin = false
     WHERE response_id = response
       AND consent_given = false;

    UPDATE survey_responses
       SET contact_allowed = true
     WHERE response_id = response
       AND fully_completed = true;

    SELECT consent_given AND fully_completed
      INTO verdict
      FROM survey_responses
     WHERE response_id = response;

    IF verdict IS NULL THEN
        RETURN false;
    END IF;

    RETURN verdict;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION tabulate_all() RETURNS TABLE (response_id integer, valid boolean) AS $$
BEGIN
    RETURN QUERY
        SELECT s.response_id, tabulate(s.response_id)
          FROM survey_responses s
         ORDER BY s.response_id;
END;
$$ LANGUAGE plpgsql;

SELECT response_id, valid
  FROM tabulate_all()
 WHERE valid = true;

SELECT response_id, completion_time, contact_allowed
  FROM survey_responses
 WHERE newsletter_optin = true
   AND fully_completed = false
 ORDER BY response_id;

