CREATE OR REPLACE FUNCTION authorize(altitude integer, temperature integer, team_size integer)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
    IF altitude > 8000 AND temperature < -30 THEN
        RETURN false;
    END IF;
    IF team_size < 3 THEN
        RETURN false;
    END IF;
    IF temperature > 0 AND team_size > 5 THEN
        RETURN true;
    END IF;
    IF altitude < 5000 THEN
        RETURN true;
    END IF;
    IF team_size > 10 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;

