RETURNS TABLE (name text, verdict text)
LANGUAGE sql
STABLE
AS $$
    SELECT e.name, 'cleared without oxygen'
    FROM expeditions e
    WHERE e.oxygen_required = false
      AND authorize(e.altitude, e.temperature, e.team_size)
    UNION ALL
    SELECT e.name, 'cleared with oxygen'
