RETURNS boolean AS $$
BEGIN
    IF velocity > 70 AND mass < 10 THEN
        RETURN false;
    END IF;

    IF brightness < 5 THEN
        RETURN false;
    END IF;

    IF mass > 1000 AND velocity < 20 THEN
        RETURN true;
    END IF;

    IF brightness > 90 THEN
        RETURN true;
    END IF;

    IF velocity > 50 AND mass > 500 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

