CREATE OR REPLACE FUNCTION admit(sight_reading integer, tone_quality integer, rhythm_accuracy integer)
RETURNS boolean AS $$
BEGIN
    IF sight_reading < 60 THEN
        RETURN false;
    END IF;

    IF tone_quality < 70 THEN
        RETURN false;
    END IF;

    IF rhythm_accuracy > 90 AND tone_quality > 90 THEN
        RETURN true;
    END IF;

    IF sight_reading = 100 AND tone_quality = 100 AND rhythm_accuracy = 100 THEN
        RETURN true;
    END IF;

    IF rhythm_accuracy < 50 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE TABLE musicians (
    id serial PRIMARY KEY,
    name text NOT NULL,
    sight_reading integer NOT NULL,
    tone_quality integer NOT NULL,
    rhythm_accuracy integer NOT NULL,
    union_member boolean NOT NULL
);

CREATE OR REPLACE FUNCTION record_musician(p_name text,
                                           p_sight integer,
                                           p_tone integer,
                                           p_rhythm integer,
                                           p_union boolean)
RETURNS boolean AS $$
DECLARE
    verdict boolean;
BEGIN
    INSERT INTO musicians (name, sight_reading, tone_quality, rhythm_accuracy, union_member)
    VALUES (p_name, p_sight, p_tone, p_rhythm, p_union);

    verdict := admit(p_sight, p_tone, p_rhythm);
    RETURN verdict;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION admission_label(p_id integer)
RETURNS text AS $$
    SELECT CASE
               WHEN admit(m.sight_reading, m.tone_quality, m.rhythm_accuracy) = true THEN 'admitted'
               ELSE 'rejected'
           END
    FROM musicians m
    WHERE m.id = $1;
$$ LANGUAGE sql STABLE;

