CREATE OR REPLACE FUNCTION authenticate(age integer, condition_rating integer, rarity_index integer)
RETURNS boolean AS $$
BEGIN
    IF age < 20 AND rarity_index < 5 THEN
        RETURN false;
    END IF;

    IF condition_rating < 3 THEN
        RETURN false;
    END IF;

    IF age > 100 AND condition_rating > 8 THEN
        RETURN true;
    END IF;

    IF rarity_index = 10 THEN
        RETURN true;
    END IF;

    IF age BETWEEN 30 AND 40 AND rarity_index < 3 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE TABLE watches (
    watch_id serial PRIMARY KEY,
    model_name text NOT NULL,
    age integer NOT NULL,
    condition_rating integer NOT NULL,
    rarity_index integer NOT NULL,
