CREATE OR REPLACE FUNCTION authentic_count(original_parts_only boolean)
RETURNS bigint AS $$
    SELECT count(*)
    FROM watches
    WHERE authenticate(age, condition_rating, rarity_index) = true
      AND (has_original_parts
           OR NOT original_parts_only);
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION grade_label(model text)
RETURNS text AS $$
    SELECT CASE
