CREATE OR REPLACE FUNCTION calculate(
    distance integer,
    wind_resistance integer,
    elevation_angle integer
) RETURNS boolean AS $$
BEGIN
    IF distance > 20000 AND wind_resistance > 50 THEN
        RETURN false;
    END IF;

    IF elevation_angle < 10 THEN
        RETURN false;
    END IF;

    IF distance < 5000 AND wind_resistance < 10 THEN
        RETURN true;
    END IF;

    IF elevation_angle = 45 THEN
        RETURN true;
    END IF;

    IF wind_resistance > 80 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

