CREATE OR REPLACE FUNCTION predict(
    seismic_tremors integer,
    sulfur_emissions integer,
    ground_deformation integer
) RETURNS boolean AS $$
BEGIN
    IF seismic_tremors < 10 AND sulfur_emissions < 20 THEN
        RETURN false;
    END IF;

    IF ground_deformation = 0 THEN
        RETURN false;
    END IF;

    IF seismic_tremors > 100 AND ground_deformation > 50 THEN
        RETURN true;
    END IF;

    IF sulfur_emissions > 200 THEN
        RETURN true;
    END IF;

    IF seismic_tremors < 5 AND ground_deformation > 10 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE volcanoes (
    id serial PRIMARY KEY,
    name text NOT NULL,
    seismic_tremors integer NOT NULL,
    sulfur_emissions integer NOT NULL,
    ground_deformation integer NOT NULL,
    near_populated_area boolean NOT NULL
);

