CREATE OR REPLACE FUNCTION alert_level(p_name text) RETURNS text AS $$
DECLARE
    v_predicted boolean;
    v_near boolean;
BEGIN
    SELECT predict(seismic_tremors, sulfur_emissions, ground_deformation), near_populated_area
      INTO v_predicted, v_near
      FROM volcanoes
     WHERE name = p_name;

    IF v_predicted = false THEN
        RETURN 'ALL CLEAR';
    END IF;

    IF v_near = true THEN
        RETURN 'EVACUATION ADVISED';
    END IF;

    RETURN 'MONITOR';
END;
$$ LANGUAGE plpgsql;

