SELECT count(*) AS at_risk_near_people
  FROM volcanoes
 WHERE near_populated_area = true
   AND predict(seismic_tremors, sulfur_emissions, ground_deformation) = true;

SELECT predict(5, 10, 5) AS quiet_case, predict(120, 100, 60) AS erupting_case;

SELECT name, alert_level(name) AS level
  FROM volcanoes
 ORDER BY name;

