CREATE TABLE players (
    player_id         serial PRIMARY KEY,
    name              text    NOT NULL,
    skating_speed     integer NOT NULL,
    blocking_strength integer NOT NULL,
    penalty_minutes   integer NOT NULL,
    team_captain      boolean NOT NULL DEFAULT false
);

CREATE OR REPLACE FUNCTION qualify(
    skating_speed     integer,
    blocking_strength integer,
    penalty_minutes   integer
) RETURNS boolean AS $$
BEGIN
    IF penalty_minutes > 50 THEN
        RETURN false;
    END IF;

    IF skating_speed < 20 AND blocking_strength < 30 THEN
        RETURN false;
    END IF;

    IF skating_speed > 80 AND blocking_strength > 80 THEN
        RETURN true;
    END IF;

    IF penalty_minutes = 0 THEN
        RETURN true;
    END IF;

    IF blocking_strength < 20 AND penalty_minutes > 20 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE OR REPLACE FUNCTION promote_captain(target_name text) RETURNS boolean AS $$
DECLARE
    promoted boolean;
BEGIN
    UPDATE players
       SET team_captain = true
     WHERE name = target_name
       AND qualify(skating_speed, blocking_strength, penalty_minutes) = true
    RETURNING true INTO promoted;

    RETURN coalesce(promoted, false);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION roster_report() RETURNS TABLE (
    name      text,
    status    text,
    is_leader boolean
) AS $$
    SELECT p.name,
           CASE WHEN qualify(p.skating_speed, p.blocking_strength, p.penalty_minutes) = false
                THEN 'cut'
                ELSE 'rostered'
           END,
           p.team_captain
      FROM players p
     ORDER BY p.team_captain DESC, p.name;
$$ LANGUAGE sql;

