CREATE OR REPLACE FUNCTION identify(cap_width integer, stem_thickness integer, spore_print_index integer)
RETURNS boolean AS $$
BEGIN
    IF spore_print_index = 4 THEN
        RETURN false;
    END IF;
    IF cap_width < 2 AND stem_thickness < 1 THEN
        RETURN false;
    END IF;
    IF cap_width > 10 AND spore_print_index = 1 THEN
        RETURN true;
    END IF;
    IF stem_thickness > 5 AND spore_print_index = 2 THEN
        RETURN true;
    END IF;
    IF cap_width > 20 AND spore_print_index = 3 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE TABLE mushrooms (
    id serial PRIMARY KEY,
    species_name text NOT NULL,
    cap_width integer NOT NULL,
    stem_thickness integer NOT NULL,
    spore_print_index integer NOT NULL,
    toxic_warning boolean NOT NULL
);

