CREATE OR REPLACE FUNCTION warned_species()
RETURNS SETOF text AS $$
    SELECT species_name
    FROM mushrooms
    WHERE toxic_warning = true
    ORDER BY species_name;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION rejected_species()
RETURNS SETOF text AS $$
    SELECT species_name
    FROM mushrooms
    WHERE identify(cap_width, stem_thickness, spore_print_index) = false
    ORDER BY species_name;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION sync_warnings()
RETURNS integer AS $$
DECLARE
    touched integer;
BEGIN
    UPDATE mushrooms
    SET toxic_warning = true
    WHERE identify(cap_width, stem_thickness, spore_print_index) = false
      AND toxic_warning = false;
    GET DIAGNOSTICS touched = ROW_COUNT;

    UPDATE mushrooms
    SET toxic_warning = false
    WHERE identify(cap_width, stem_thickness, spore_print_index) = true
      AND toxic_warning = true;
    RETURN touched;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM mushrooms WHERE toxic_warning = true;

SELECT * FROM mushrooms
WHERE identify(cap_width, stem_thickness, spore_print_index) = false;

SELECT sync_warnings() AS newly_flagged;
SELECT warned_species() AS warned;
SELECT rejected_species() AS rejected;

