CREATE OR REPLACE FUNCTION clear(tunnel_width integer, water_depth integer, oxygen_level integer)
RETURNS boolean AS $$
BEGIN
    IF oxygen_level < 80 THEN
        RETURN false;
    END IF;
    IF water_depth > 50 AND tunnel_width < 20 THEN
        RETURN false;
    END IF;
    IF tunnel_width > 100 AND water_depth < 10 THEN
        RETURN true;
    END IF;
    IF oxygen_level = 100 THEN
        RETURN true;
    END IF;
    IF tunnel_width < 10 AND water_depth > 20 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE TABLE routes (
    id              serial PRIMARY KEY,
    name            text NOT NULL,
    tunnel_width    integer NOT NULL,
    water_depth     integer NOT NULL,
    oxygen_level    integer NOT NULL,
    mapped_entirely boolean NOT NULL
);

CREATE TABLE assessments (
    route_id      integer PRIMARY KEY REFERENCES routes(id),
    is_clear      boolean NOT NULL,
    needs_revisit boolean NOT NULL
);

INSERT INTO routes (name, tunnel_width, water_depth, oxygen_level, mapped_entirely)
VALUES ('Siphon Gallery', 30, 10, 75, true);

INSERT INTO routes (name, tunnel_width, water_depth, oxygen_level, mapped_entirely)
VALUES ('Dry Crawl', 120, 5, 90, false);

CREATE OR REPLACE FUNCTION refresh_assessments() RETURNS integer AS $$
DECLARE
    rebuilt integer;
BEGIN
    DELETE FROM assessments;
    INSERT INTO assessments (route_id, is_clear, needs_revisit)
    SELECT r.id,
           clear(r.tunnel_width, r.water_depth, r.oxygen_level),
           NOT clear(r.tunnel_width, r.water_depth, r.oxygen_level)
    FROM routes r;
    SELECT count(*) INTO rebuilt FROM assessments;
    RETURN rebuilt;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION finish_mapping(target_id integer) RETURNS boolean AS $$
DECLARE
    done boolean;
BEGIN
    UPDATE routes SET mapped_entirely = true
    WHERE id = target_id AND NOT mapped_entirely
    RETURNING mapped_entirely INTO done;
    RETURN coalesce(done, false);
END;
$$ LANGUAGE plpgsql;

SELECT clear(30, 10, 75) AS siphon_gallery_clear;
SELECT clear(120, 5, 90) AS dry_crawl_clear;

