CREATE OR REPLACE FUNCTION warn(snowpack_depth integer, temperature_gradient integer, slope_angle integer)
RETURNS boolean AS $$
BEGIN
    IF snowpack_depth < 0 OR temperature_gradient < 0 OR slope_angle < 0 THEN
        RAISE EXCEPTION 'snowpack, gradient and slope metrics must be non-negative';
    END IF;

    IF slope_angle < 20 THEN
        RETURN false;
    END IF;

    IF snowpack_depth > 200 AND temperature_gradient < 5 THEN
        RETURN false;
    END IF;

    IF slope_angle BETWEEN 30 AND 45 AND temperature_gradient > 15 THEN
        RETURN true;
    END IF;

    IF snowpack_depth > 300 AND slope_angle > 50 THEN
        RETURN true;
    END IF;

    IF temperature_gradient < 2 AND slope_angle < 30 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE TABLE mountain_faces (
    id serial PRIMARY KEY,
