CREATE OR REPLACE FUNCTION pending_mitigation()
RETURNS TABLE (location text, slope_angle integer) AS $$
    SELECT m.location, m.slope_angle
    FROM mountain_faces m
    WHERE m.explosive_triggered = false
      AND warn(m.snowpack_depth, m.temperature_gradient, m.slope_angle) = true
    ORDER BY m.slope_angle DESC;
$$ LANGUAGE sql STABLE;

