CREATE OR REPLACE FUNCTION compose(
    base_longevity integer,
    top_intensity integer,
    alcohol_percentage integer
) RETURNS boolean AS $$
BEGIN
    IF alcohol_percentage > 90 THEN
        RETURN false;
    END IF;

    IF base_longevity < 2 AND top_intensity < 3 THEN
        RETURN false;
    END IF;

    IF base_longevity > 8 AND alcohol_percentage < 70 THEN
        RETURN true;
    END IF;

    IF top_intensity = 10 AND base_longevity > 5 THEN
        RETURN true;
    END IF;

    IF alcohol_percentage > 80 AND base_longevity < 4 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

