CREATE OR REPLACE FUNCTION train(flight_speed integer, recall_obedience integer, prey_size integer)
RETURNS boolean AS $$
BEGIN
    IF recall_obedience < 40 THEN
        RETURN false;
    END IF;

    IF flight_speed < 50 AND prey_size > 20 THEN
        RETURN false;
    END IF;

    IF recall_obedience > 90 AND flight_speed > 80 THEN
        RETURN true;
    END IF;

    IF prey_size = 5 AND recall_obedience > 80 THEN
        RETURN true;
    END IF;

    IF flight_speed < 30 AND recall_obedience < 60 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE TABLE falcons (
    id              serial PRIMARY KEY,
    name            text NOT NULL,
    flight_speed    integer NOT NULL CHECK (flight_speed BETWEEN 0 AND 100),
    recall_obedience integer NOT NULL CHECK (recall_obedience BETWEEN 0 AND 100),
    prey_size       integer NOT NULL CHECK (prey_size BETWEEN 0 AND 100),
    captive_bred    boolean NOT NULL
);

INSERT INTO falcons (name, flight_speed, recall_obedience, prey_size, captive_bred)
VALUES ('Kestrel Kate', 60, 30, 10, true);

INSERT INTO falcons (name, flight_speed, recall_obedience, prey_size, captive_bred)
VALUES ('Peregrine Pete', 85, 95, 10, false);

CREATE OR REPLACE FUNCTION release_candidates()
RETURNS TABLE (name text, flight_speed integer) AS $$
    SELECT f.name, f.flight_speed
    FROM falcons f
    WHERE f.captive_bred = false
      AND train(f.flight_speed, f.recall_obedience, f.prey_size) = true
    ORDER BY f.name;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION status_report()
RETURNS TABLE (name text, origin text, verdict text) AS $$
    SELECT f.name,
           CASE WHEN f.captive_bred THEN 'captive bred' ELSE 'wild caught' END,
           CASE WHEN train(f.flight_speed, f.recall_obedience, f.prey_size)
                THEN 'ready for the field' ELSE 'needs more training' END
    FROM falcons f
    ORDER BY f.id;
$$ LANGUAGE sql STABLE;

SELECT name, flight_speed, recall_obedience, prey_size
FROM falcons
WHERE captive_bred = true;

SELECT name, flight_speed, recall_obedience, prey_size
FROM falcons
WHERE train(flight_speed, recall_obedience, prey_size) = false;

SELECT * FROM release_candidates();

SELECT * FROM status_report();

SELECT train(60, 30, 10) AS kate_trained, train(85, 95, 10) AS pete_trained;

UPDATE falcons
SET recall_obedience = 55
WHERE captive_bred = true
  AND train(flight_speed, recall_obedience, prey_size) = false;

SELECT name, recall_obedience
FROM falcons
WHERE train(flight_speed, recall_obedience, prey_size) = true
ORDER BY name;

