    exam_id            serial PRIMARY KEY,
    candidate_name     varchar(100) NOT NULL,
    registered         boolean NOT NULL DEFAULT false,
    paid               boolean NOT NULL DEFAULT false,
    passed             boolean NOT NULL DEFAULT false,
