    bench_id TEXT PRIMARY KEY,
    is_calibrated BOOLEAN NOT NULL
);

INSERT INTO instruments (bench_id, is_calibrated) VALUES ('electron imager', true);
INSERT INTO instruments (bench_id, is_calibrated) VALUES ('phase contrast scope', false);
INSERT INTO instruments (bench_id, is_calibrated) VALUES ('fluorescence analyzer', true);
INSERT INTO instruments (bench_id, is_calibrated) VALUES ('stereo magnifier', true);
INSERT INTO instruments (bench_id, is_calibrated) VALUES ('confocal laser module', false);
INSERT INTO instruments (bench_id, is_calibrated) VALUES ('metallurgical viewer', false);
INSERT INTO instruments (bench_id, is_calibrated) VALUES ('inverted tissue scope', true);
INSERT INTO instruments (bench_id, is_calibrated) VALUES ('atomic force probe', false);

CREATE TABLE calibration_log (
    log_id SERIAL PRIMARY KEY,
    bench_id TEXT NOT NULL,
    action TEXT NOT NULL,
    new_state BOOLEAN
);

CREATE FUNCTION list_calibrated() RETURNS SETOF TEXT AS $$
    SELECT bench_id
    FROM instruments
    WHERE is_calibrated = true
    ORDER BY bench_id;
$$ LANGUAGE sql;

CREATE FUNCTION list_pending() RETURNS SETOF TEXT AS $$
    SELECT bench_id
    FROM instruments
    WHERE is_calibrated = false
    ORDER BY bench_id;
$$ LANGUAGE sql;

CREATE FUNCTION calibrate(p_bench TEXT) RETURNS BOOLEAN AS $$
DECLARE
    v_found BOOLEAN;
BEGIN
    UPDATE instruments
    SET is_calibrated = true
    WHERE bench_id = p_bench;

    v_found := FOUND;

    IF v_found THEN
        INSERT INTO calibration_log (bench_id, action, new_state)
        VALUES (p_bench, 'calibrated', true);
    END IF;

    RETURN v_found;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION purge_uncalibrated() RETURNS INTEGER AS $$
DECLARE
    v_removed INTEGER;
BEGIN
    INSERT INTO calibration_log (bench_id, action, new_state)
    SELECT bench_id, 'purged', false
    FROM instruments
    WHERE is_calibrated = false;

    DELETE FROM instruments
    WHERE is_calibrated = false;

    GET DIAGNOSTICS v_removed = ROW_COUNT;
    RETURN v_removed;
END;
$$ LANGUAGE plpgsql;

SELECT bench_id FROM instruments WHERE is_calibrated = true ORDER BY bench_id;

SELECT * FROM list_pending();

SELECT calibrate('phase contrast scope');

SELECT * FROM list_calibrated();

SELECT purge_uncalibrated() AS benches_removed;

SELECT bench_id, action FROM calibration_log WHERE new_state = false ORDER BY log_id;

SELECT bench_id, is_calibrated FROM instruments ORDER BY bench_id;

