CREATE OR REPLACE PROCEDURE setup()
LANGUAGE plpgsql AS $$
BEGIN
    DROP VIEW IF EXISTS painted_boards;
    DROP VIEW IF EXISTS unsanded_boards;
    DROP VIEW IF EXISTS fiberglassed_boards;
    DROP TABLE IF EXISTS surfboards;

    CREATE TABLE surfboards (
        board_id     SERIAL PRIMARY KEY,
        model        TEXT NOT NULL,
        length_cm    INTEGER NOT NULL,
        fiberglassed BOOLEAN NOT NULL DEFAULT false,
        sanded       BOOLEAN NOT NULL DEFAULT false,
        painted      BOOLEAN NOT NULL DEFAULT false
    );

    CREATE VIEW fiberglassed_boards AS
        SELECT board_id, model, length_cm
          FROM surfboards
         WHERE fiberglassed = true;

    CREATE VIEW unsanded_boards AS
        SELECT board_id, model, length_cm
          FROM surfboards
         WHERE sanded = false;

    CREATE VIEW painted_boards AS
        SELECT board_id, model, length_cm
          FROM surfboards
         WHERE painted = true;
END;
$$;

CREATE OR REPLACE PROCEDURE fiberglass(p_board_id INTEGER)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE surfboards SET fiberglassed = true WHERE board_id = p_board_id;
END;
$$;

CREATE OR REPLACE PROCEDURE strip_fiberglass(p_board_id INTEGER)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE surfboards SET fiberglassed = false WHERE board_id = p_board_id;
END;
$$;

CREATE OR REPLACE PROCEDURE sand(p_board_id INTEGER)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE surfboards SET sanded = true
     WHERE board_id = p_board_id
       AND fiberglassed = true;
END;
$$;

CREATE OR REPLACE PROCEDURE roughen(p_board_id INTEGER)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE surfboards SET sanded = false WHERE board_id = p_board_id;
END;
$$;

CREATE OR REPLACE PROCEDURE paint(p_board_id INTEGER)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE surfboards SET painted = true
     WHERE board_id = p_board_id
       AND sanded = true;
END;
$$;

