CREATE OR REPLACE PROCEDURE prepare()
LANGUAGE plpgsql AS $$
BEGIN
    CREATE TABLE IF NOT EXISTS open_mic_comedians (
        comedian_id   SERIAL PRIMARY KEY,
        stage_name    TEXT NOT NULL UNIQUE,
        signup_slot   INTEGER NOT NULL,
        is_local      BOOLEAN NOT NULL DEFAULT false,
        needs_stand   BOOLEAN NOT NULL DEFAULT false,
        has_performed BOOLEAN NOT NULL DEFAULT false
    );
    TRUNCATE open_mic_comedians RESTART IDENTITY;
END;
$$;

CREATE OR REPLACE PROCEDURE flag_as_local(p_name TEXT)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE open_mic_comedians
       SET is_local = true
     WHERE stage_name = p_name
       AND is_local = false;
END;
$$;

CREATE OR REPLACE PROCEDURE mark_as_traveling(p_name TEXT)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE open_mic_comedians
       SET is_local = false
     WHERE stage_name = p_name
       AND is_local = true;
