BEGIN
    CREATE TABLE IF NOT EXISTS clothing_alterations (
        alteration_id integer PRIMARY KEY,
        garment       text    NOT NULL,
        is_pinned     boolean NOT NULL DEFAULT false,
        is_hemmed     boolean NOT NULL DEFAULT false,
        is_steamed    boolean NOT NULL DEFAULT false
    );
END;
$$;

CREATE OR REPLACE PROCEDURE pin_garment(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE clothing_alterations
       SET is_pinned = true
     WHERE alteration_id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'no alteration ticket %', p_id;
    END IF;
END;
$$;

CREATE OR REPLACE PROCEDURE unpin_garment(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE clothing_alterations
       SET is_pinned = false
     WHERE alteration_id = p_id
       AND is_hemmed = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ticket % is not hemmed yet, pins must stay', p_id;
    END IF;
END;
$$;

CREATE OR REPLACE PROCEDURE hem_garment(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE clothing_alterations
       SET is_hemmed = true
     WHERE alteration_id = p_id
       AND is_pinned = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ticket % must be pinned before hemming', p_id;
    END IF;
END;
$$;

CREATE OR REPLACE PROCEDURE unhem_garment(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE clothing_alterations
       SET is_hemmed  = false,
           is_steamed = false
     WHERE alteration_id = p_id;
END;
$$;

CREATE OR REPLACE PROCEDURE steam_garment(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE clothing_alterations
       SET is_steamed = true
     WHERE alteration_id = p_id
       AND is_hemmed = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ticket % cannot be steamed before the hem is set', p_id;
    END IF;
END;
$$;

CALL install();

