CREATE TABLE skydiving_jumps (
    jump_id       integer PRIMARY KEY,
    jumper_name   text NOT NULL,
    altitude_ft   integer NOT NULL,
    waiver_signed boolean NOT NULL DEFAULT false,
    gear_checked  boolean NOT NULL DEFAULT false,
    completed     boolean NOT NULL DEFAULT false
);

CREATE OR REPLACE PROCEDURE build()
LANGUAGE plpgsql AS $$
BEGIN
    TRUNCATE skydiving_jumps;
    INSERT INTO skydiving_jumps (jump_id, jumper_name, altitude_ft, waiver_signed)
    VALUES (1, 'Ines Falk', 13000, true);
END;
$$;

CREATE OR REPLACE PROCEDURE add_jump(p_jump_id integer, p_name text, p_altitude integer,
                                     p_waiver_signed boolean)
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO skydiving_jumps (jump_id, jumper_name, altitude_ft, waiver_signed)
    VALUES (p_jump_id, p_name, p_altitude, p_waiver_signed);
END;
$$;

CREATE OR REPLACE PROCEDURE sign_waiver(p_jump_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE skydiving_jumps
       SET waiver_signed = true
     WHERE jump_id = p_jump_id;
END;
$$;

CREATE OR REPLACE PROCEDURE invalidate_waiver(p_jump_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE skydiving_jumps
       SET waiver_signed = false
     WHERE jump_id = p_jump_id;
END;
$$;

CREATE OR REPLACE PROCEDURE check_gear(p_jump_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE skydiving_jumps
       SET gear_checked = true
     WHERE jump_id = p_jump_id;
END;
$$;

CREATE OR REPLACE PROCEDURE uncheck_gear(p_jump_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE skydiving_jumps
       SET gear_checked = false
     WHERE jump_id = p_jump_id;
END;
$$;

CREATE OR REPLACE PROCEDURE complete_jump(p_jump_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE skydiving_jumps
       SET completed = true
     WHERE jump_id = p_jump_id
       AND waiver_signed = true
       AND gear_checked = true;
END;
$$;

CREATE OR REPLACE VIEW signed_jumps AS
SELECT jump_id, jumper_name, altitude_ft
  FROM skydiving_jumps
 WHERE waiver_signed = true;

CREATE OR REPLACE VIEW unchecked_gear_jumps AS
SELECT jump_id, jumper_name, altitude_ft
  FROM skydiving_jumps
 WHERE gear_checked = false;

CREATE OR REPLACE VIEW completed_jumps AS
SELECT jump_id, jumper_name, altitude_ft
  FROM skydiving_jumps
 WHERE completed = true;

