CREATE OR REPLACE PROCEDURE prepare()
LANGUAGE plpgsql AS $$
BEGIN
    DROP VIEW IF EXISTS lit_sculptures;
    DROP VIEW IF EXISTS idle_sculptures;
    DROP VIEW IF EXISTS delivered_blocks;
    DROP TABLE IF EXISTS ice_sculptures;

    CREATE TABLE ice_sculptures (
        id          serial PRIMARY KEY,
        title       text NOT NULL,
        delivered   boolean NOT NULL DEFAULT false,
        started     boolean NOT NULL DEFAULT false,
        illuminated boolean NOT NULL DEFAULT false
    );

    CREATE VIEW delivered_blocks AS
        SELECT id, title, started FROM ice_sculptures WHERE delivered = true;

    CREATE VIEW idle_sculptures AS
        SELECT id, title, delivered FROM ice_sculptures WHERE started = false;

    CREATE VIEW lit_sculptures AS
        SELECT id, title FROM ice_sculptures WHERE illuminated = true;
END;
$$;

CREATE OR REPLACE PROCEDURE deliver_block(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE ice_sculptures SET delivered = true WHERE id = p_id;
END;
$$;

CREATE OR REPLACE PROCEDURE return_block(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE ice_sculptures SET delivered = false WHERE id = p_id;
END;
$$;

CREATE OR REPLACE PROCEDURE start_carving(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE ice_sculptures SET started = true
    WHERE id = p_id AND delivered = true;
END;
$$;

CREATE OR REPLACE PROCEDURE pause_carving(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE ice_sculptures SET started = false WHERE id = p_id;
END;
$$;

CREATE OR REPLACE PROCEDURE illuminate(p_id integer)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE ice_sculptures SET illuminated = true
    WHERE id = p_id AND started = true;
END;
$$;

DO $$
DECLARE
    v_swan integer;
    v_bear integer;
    v_count integer;
    v_lit text;
BEGIN
    CALL prepare();

    INSERT INTO ice_sculptures (title, delivered)
    VALUES ('Swan', true) RETURNING id INTO v_swan;

    INSERT INTO ice_sculptures (title, delivered)
    VALUES ('Bear', false) RETURNING id INTO v_bear;

    CALL start_carving(v_swan);
    CALL illuminate(v_swan);
    CALL deliver_block(v_bear);
    CALL start_carving(v_bear);
    CALL pause_carving(v_bear);
    CALL return_block(v_bear);

    SELECT count(*) INTO v_count FROM delivered_blocks;
    RAISE NOTICE 'delivered blocks: %', v_count;

    SELECT count(*) INTO v_count FROM idle_sculptures WHERE delivered = false;
    RAISE NOTICE 'idle and undelivered: %', v_count;

    SELECT string_agg(title, ', ') INTO v_lit FROM lit_sculptures;
    RAISE NOTICE 'illuminated sculptures: %', coalesce(v_lit, 'none');
END;
$$;

