CREATE OR REPLACE PROCEDURE configure() LANGUAGE plpgsql AS $$
BEGIN
    DROP TABLE IF EXISTS rockets CASCADE;
    CREATE TABLE rockets (
        rocket_id   integer PRIMARY KEY,
        name        text NOT NULL,
        fuse_wired  boolean NOT NULL DEFAULT false,
        angle_set   boolean NOT NULL DEFAULT false,
        launched    boolean NOT NULL DEFAULT false
    );
END;
$$;

CREATE OR REPLACE PROCEDURE wire_fuse(p_id integer) LANGUAGE plpgsql AS $$
BEGIN
    UPDATE rockets SET fuse_wired = true
     WHERE rocket_id = p_id
       AND launched = false;
END;
$$;

CREATE OR REPLACE PROCEDURE disconnect_fuse(p_id integer) LANGUAGE plpgsql AS $$
BEGIN
    UPDATE rockets SET fuse_wired = false
     WHERE rocket_id = p_id
       AND launched = false;
END;
$$;

CREATE OR REPLACE PROCEDURE set_angle(p_id integer) LANGUAGE plpgsql AS $$
BEGIN
    UPDATE rockets SET angle_set = true
     WHERE rocket_id = p_id
       AND launched = false;
END;
$$;

CREATE OR REPLACE PROCEDURE reset_angle(p_id integer) LANGUAGE plpgsql AS $$
BEGIN
    UPDATE rockets SET angle_set = false
     WHERE rocket_id = p_id
       AND launched = false;
END;
$$;

CREATE OR REPLACE PROCEDURE launch(p_id integer) LANGUAGE plpgsql AS $$
BEGIN
    UPDATE rockets SET launched = true
     WHERE rocket_id = p_id
       AND fuse_wired = true
       AND angle_set = true;
END;
$$;

CALL configure();

CREATE OR REPLACE VIEW wired_rockets AS
SELECT rocket_id, name FROM rockets WHERE fuse_wired = true;

CREATE OR REPLACE VIEW unaimed_rockets AS
SELECT rocket_id, name FROM rockets WHERE angle_set = false;

CREATE OR REPLACE VIEW launched_rockets AS
SELECT rocket_id, name FROM rockets WHERE launched = true;

