    username          VARCHAR(50) NOT NULL,
    registration_date DATE NOT NULL,
    is_active         BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE Posts (
    post_id        INT PRIMARY KEY,
    user_id        INT NOT NULL REFERENCES Users(user_id),
    post_text      TEXT NOT NULL,
    post_timestamp TIMESTAMP NOT NULL,
    is_deleted     BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE Likes (
    like_id      INT PRIMARY KEY,
    post_id      INT NOT NULL REFERENCES Posts(post_id),
    user_id      INT NOT NULL REFERENCES Users(user_id),
    is_retracted BOOLEAN NOT NULL DEFAULT FALSE,
    UNIQUE (post_id, user_id)
);

CREATE VIEW v_posts_with_authors AS
    SELECT p.post_id, p.post_text, p.post_timestamp, u.user_id, u.username
    FROM Posts p
    JOIN Users u ON u.user_id = p.user_id
    WHERE p.is_deleted = FALSE;

CREATE FUNCTION create_post(p_user_id INT, p_post_text TEXT) RETURNS INT AS $$
DECLARE v_post_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Users WHERE user_id = p_user_id AND is_active = TRUE) THEN
        RAISE EXCEPTION 'user % may not post', p_user_id;
    END IF;
    SELECT COALESCE(MAX(post_id), 0) + 1 INTO v_post_id FROM Posts;
    INSERT INTO Posts (post_id, user_id, post_text, post_timestamp, is_deleted)
    VALUES (v_post_id, p_user_id, p_post_text, now(), FALSE);
    RETURN v_post_id;
END;
$$ LANGUAGE plpgsql;

