CREATE TABLE Suppliers (
    supplier_id INT PRIMARY KEY,
    supplier_name VARCHAR(255),
    contact_email VARCHAR(255)
);

CREATE TABLE Products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(255),
    supplier_id INT,
    current_stock INT,
    reorder_level INT,
    is_active BOOLEAN
);

INSERT INTO Suppliers (supplier_id, supplier_name, contact_email) VALUES
(1, 'Alpha Supplies', 'alpha@example.com'),
(2, 'Beta Distributors', 'beta@example.com');

INSERT INTO Products (product_id, product_name, supplier_id, current_stock, reorder_level, is_active) VALUES
(101, 'Laptop Pro', 1, 10, 15, true),
(102, 'Mouse Wireless', 1, 50, 20, true),
(103, 'Keyboard Mechanical', 2, 8, 10, false),
(104, 'Webcam HD', 2, 12, 5, true);

-- 1. Select all products that are below their reorder level.
SELECT product_name, current_stock, reorder_level FROM Products WHERE current_stock < reorder_level AND is_active = true;

-- 2. Find all products supplied by a specific supplier (e.g., supplier_id = 1).
SELECT product_name FROM Products WHERE supplier_id = 1 AND is_active = true;

-- 3. Calculate the total current stock of all products.
SELECT SUM(current_stock) FROM Products WHERE is_active = true;

