INSERT INTO Products (product_id, product_name, supplier_id, current_stock, reorder_level, is_active) VALUES (105, 'Monitor Ultrawide', 1, 7, 10, true);

-- 5. Update a product's current stock after receiving new inventory.
UPDATE Products SET current_stock = current_stock + 20 WHERE product_id = 101 AND is_active = true;

