    DishName VARCHAR(100),
    Category VARCHAR(50),
    Price DECIMAL(10,2)
);

CREATE TABLE Orders (
    OrderID INT PRIMARY KEY,
    OrderDate DATETIME,
    TableNumber INT,
    TotalAmount DECIMAL(10,2)
);

CREATE TABLE OrderItems (
    OrderItemID INT PRIMARY KEY,
    OrderID INT,
    DishID INT,
    Quantity INT,
    PriceAtOrder DECIMAL(10,2),
    IsSpecialRequest BOOLEAN
);

