CREATE OR REPLACE FUNCTION active_participants(p_trial_name VARCHAR)
RETURNS TABLE (ParticipantID INT, FirstName VARCHAR, LastName VARCHAR, EnrollmentDate DATE)
LANGUAGE sql AS $$
    SELECT p.ParticipantID, p.FirstName, p.LastName, tp.EnrollmentDate
    FROM Participants p
    JOIN TrialParticipants tp ON tp.ParticipantID = p.ParticipantID
    JOIN Trials t ON t.TrialID = tp.TrialID
    WHERE t.TrialName = p_trial_name
      AND tp.Status = 'Active'
      AND tp.IsWithdrawn = false
    ORDER BY p.LastName, p.FirstName;
$$;

-- 2. Number of participants per trial
CREATE OR REPLACE FUNCTION participant_counts()
RETURNS TABLE (TrialID INT, TrialName VARCHAR, ParticipantCount BIGINT)
LANGUAGE sql AS $$
    SELECT t.TrialID, t.TrialName, COUNT(tp.ParticipantID)
    FROM Trials t
    LEFT JOIN TrialParticipants tp
           ON tp.TrialID = t.TrialID AND tp.IsWithdrawn = false
    GROUP BY t.TrialID, t.TrialName
    ORDER BY t.TrialID;
$$;

-- 3. Participants enrolled in more than one trial
CREATE OR REPLACE FUNCTION multi_trial_participants()
RETURNS TABLE (ParticipantID INT, FullName TEXT, Trials BIGINT)
LANGUAGE sql AS $$
    SELECT p.ParticipantID,
           p.FirstName || ' ' || p.LastName,
           COUNT(DISTINCT tp.TrialID)
    FROM Participants p
    JOIN TrialParticipants tp ON tp.ParticipantID = p.ParticipantID
    WHERE tp.IsWithdrawn = false
    GROUP BY p.ParticipantID, p.FirstName, p.LastName
    HAVING COUNT(DISTINCT tp.TrialID) > 1;
$$;

-- 4. Enroll a participant (only consenting participants into running trials)
CREATE OR REPLACE FUNCTION enroll_participant(p_trial_id INT, p_participant_id INT, p_date DATE)
RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO TrialParticipants (TrialID, ParticipantID, EnrollmentDate, Status, IsWithdrawn)
    SELECT t.TrialID, p.ParticipantID, p_date, 'Active', false
    FROM Trials t, Participants p
    WHERE t.TrialID = p_trial_id
      AND t.IsActive = true
      AND p.ParticipantID = p_participant_id
      AND p.ConsentGiven = true;
    RETURN FOUND;
END;
$$;

-- 5. Mark a participation as completed
CREATE OR REPLACE FUNCTION complete_participation(p_trial_id INT, p_participant_id INT)
RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE TrialParticipants
    SET Status = 'Completed'
    WHERE TrialID = p_trial_id
      AND ParticipantID = p_participant_id
      AND IsWithdrawn = false;
    RETURN FOUND;
END;
$$;

