-- Boolean flags the enrollment workflow needs on top of the base schema
CREATE TABLE Users (
    UserID   INT PRIMARY KEY,
    UserName VARCHAR(100),
    IsActive BOOLEAN NOT NULL DEFAULT true
);
ALTER TABLE Courses     ADD COLUMN IsPublished BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE Enrollments ADD COLUMN IsActive    BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE Progress    ADD COLUMN IsVerified  BOOLEAN NOT NULL DEFAULT false;

-- 1. 'In Progress' modules for 'User A' in 'Introduction to SQL'
CREATE VIEW UserAPendingSQLModules AS
SELECT m.OrderInCourse, m.ModuleName, p.CompletionStatus
FROM Progress p
JOIN Enrollments e ON e.EnrollmentID = p.EnrollmentID
JOIN Users u       ON u.UserID = e.UserID
JOIN Modules m     ON m.ModuleID = p.ModuleID
JOIN Courses c     ON c.CourseID = e.CourseID
WHERE u.UserName = 'User A'
  AND c.CourseName = 'Introduction to SQL'
  AND p.CompletionStatus = 'In Progress'
ORDER BY m.OrderInCourse;

-- 2. Percentage of modules completed by each user in one course
CREATE FUNCTION course_completion_pct(p_course_id INT)
RETURNS TABLE (UserID INT, UserName VARCHAR(100), PctCompleted NUMERIC) AS $$
    SELECT u.UserID, u.UserName,
           ROUND(100.0 * COUNT(*) FILTER (WHERE p.CompletionStatus = 'Completed')
                 / NULLIF((SELECT COUNT(*) FROM Modules mt
                            WHERE mt.CourseID = p_course_id), 0), 2)
    FROM Enrollments e
    JOIN Users u          ON u.UserID = e.UserID
    LEFT JOIN Progress p  ON p.EnrollmentID = e.EnrollmentID
    WHERE e.CourseID = p_course_id
    GROUP BY u.UserID, u.UserName;
$$ LANGUAGE sql;

-- 3. Courses where every enrolled student has completed at least half the modules
CREATE VIEW CoursesAtHalfwayOrBetter AS
SELECT c.CourseID, c.CourseName, c.Instructor
FROM Courses c
WHERE EXISTS (SELECT 1 FROM Enrollments e2 WHERE e2.CourseID = c.CourseID)
  AND NOT EXISTS (
        SELECT 1
        FROM Enrollments e
        WHERE e.CourseID = c.CourseID
          AND 2 * (SELECT COUNT(*) FROM Progress p
                   WHERE p.EnrollmentID = e.EnrollmentID
                     AND p.CompletionStatus = 'Completed')
              < (SELECT COUNT(*) FROM Modules mt WHERE mt.CourseID = c.CourseID));

-- 4. Enroll a user and mark the first module as 'Completed'
CREATE FUNCTION enroll_user(p_user_id INT, p_course_id INT) RETURNS INT AS $$
DECLARE v_enrollment INT; v_module INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Users
                    WHERE UserID = p_user_id AND IsActive = true) THEN
        RAISE EXCEPTION 'User % is not active', p_user_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Courses
                    WHERE CourseID = p_course_id AND IsPublished = true) THEN
        RAISE EXCEPTION 'Course % is not open for enrollment', p_course_id;
    END IF;
    SELECT EnrollmentID INTO v_enrollment FROM Enrollments
     WHERE UserID = p_user_id AND CourseID = p_course_id AND IsActive = true;
    IF v_enrollment IS NOT NULL THEN
        RETURN v_enrollment;
    END IF;
    SELECT COALESCE(MAX(EnrollmentID), 0) + 1 INTO v_enrollment FROM Enrollments;
    INSERT INTO Enrollments (EnrollmentID, UserID, CourseID, StartDate, CompletionDate, IsActive)
    VALUES (v_enrollment, p_user_id, p_course_id, CURRENT_DATE, NULL, true);
    SELECT ModuleID INTO v_module FROM Modules
     WHERE CourseID = p_course_id ORDER BY OrderInCourse LIMIT 1;
    INSERT INTO Progress (ProgressID, EnrollmentID, ModuleID, CompletionStatus, CompletionDate, IsVerified)
    VALUES ((SELECT COALESCE(MAX(ProgressID), 0) + 1 FROM Progress),
            v_enrollment, v_module, 'Completed', NOW(), false);
    RETURN v_enrollment;
END; $$ LANGUAGE plpgsql;

-- 5. Update (or create) the progress row holding a module's status for a user
CREATE FUNCTION set_module_status(p_user_id INT, p_course_id INT,
                                 p_module_id INT, p_status VARCHAR(20)) RETURNS VOID AS $$
DECLARE v_rows INT; v_enrollment INT;
BEGIN
    UPDATE Progress p
       SET CompletionStatus = p_status,
           CompletionDate = CASE WHEN p_status = 'Completed' THEN NOW() END,
           IsVerified = false
      FROM Enrollments e
     WHERE e.EnrollmentID = p.EnrollmentID
       AND p.ModuleID = p_module_id
       AND e.UserID = p_user_id
       AND e.CourseID = p_course_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
        SELECT EnrollmentID INTO STRICT v_enrollment FROM Enrollments
         WHERE UserID = p_user_id AND CourseID = p_course_id;
        INSERT INTO Progress (ProgressID, EnrollmentID, ModuleID, CompletionStatus, CompletionDate, IsVerified)
        VALUES ((SELECT COALESCE(MAX(ProgressID), 0) + 1 FROM Progress),
                v_enrollment, p_module_id, p_status,
                CASE WHEN p_status = 'Completed' THEN NOW() END, false);
    END IF;
END; $$ LANGUAGE plpgsql;

-- Driver
SELECT enroll_user(u.UserID, c.CourseID)
FROM Users u, Courses c
WHERE u.UserName = 'User B' AND c.CourseName = 'Introduction to SQL';

SELECT set_module_status(u.UserID, m.CourseID, m.ModuleID, 'In Progress')
FROM Users u, Modules m
JOIN Courses c ON c.CourseID = m.CourseID
WHERE u.UserName = 'User B'
  AND c.CourseName = 'Introduction to SQL'
  AND m.OrderInCourse = 2;

SELECT * FROM UserAPendingSQLModules;
SELECT * FROM course_completion_pct(
    (SELECT CourseID FROM Courses WHERE CourseName = 'Introduction to SQL'));
SELECT * FROM CoursesAtHalfwayOrBetter;

