create table documents (
    doc_id            integer primary key,
    title             text not null,
    latest_version_id integer,
    is_archived       boolean not null default false
);

create table versions (
    version_id     serial primary key,
    doc_id         integer not null references documents(doc_id),
    version_number integer not null,
    content        text not null,
    created_at     timestamptz not null default now(),
    created_by     text not null,
    is_current     boolean not null default false,
    unique (doc_id, version_number)
);

create function get_latest_content(p_doc_id integer) returns text as $$
    select v.content
    from versions v
    join documents d on d.doc_id = v.doc_id
    where v.doc_id = p_doc_id
      and v.is_current = true
      and d.is_archived = false;
$$ language sql stable;

create function get_document_versions(p_doc_id integer)
returns table (version_number integer, created_by text, created_at timestamptz, is_current boolean) as $$
    select v.version_number, v.created_by, v.created_at, v.is_current
    from versions v
    where v.doc_id = p_doc_id
    order by v.version_number;
$$ language sql stable;

create function add_version(p_doc_id integer, p_content text, p_author text) returns integer as $$
declare
    v_next integer;
    v_new_id integer;
begin
    if not exists (select 1 from documents where doc_id = p_doc_id and is_archived = false) then
        raise exception 'document % is missing or archived', p_doc_id;
    end if;

    select coalesce(max(version_number), 0) + 1 into v_next
    from versions
    where doc_id = p_doc_id;

    update versions
       set is_current = false
     where doc_id = p_doc_id
       and is_current = true;

    insert into versions (doc_id, version_number, content, created_by, is_current)
    values (p_doc_id, v_next, p_content, p_author, true)
    returning version_id into v_new_id;

    update documents
       set latest_version_id = v_new_id
     where doc_id = p_doc_id;

    return v_new_id;
end;
$$ language plpgsql;

create function documents_by_author(p_author text)
returns table (doc_id integer, title text, contributions bigint) as $$
    select d.doc_id, d.title, count(*)
    from documents d
    join versions v on v.doc_id = d.doc_id
    where v.created_by = p_author
      and d.is_archived = false
    group by d.doc_id, d.title
    order by d.doc_id;
$$ language sql stable;

create function version_counts()
returns table (doc_id integer, title text, total_versions bigint, superseded bigint) as $$
    select d.doc_id,
           d.title,
           count(v.version_id),
           count(v.version_id) filter (where v.is_current = false)
    from documents d
    left join versions v on v.doc_id = d.doc_id
    group by d.doc_id, d.title
    order by d.doc_id;
$$ language sql stable;

insert into documents (doc_id, title, is_archived) values
    (1, 'Deployment Runbook', false),
    (2, 'Legacy Pricing Sheet', true);

select add_version(1, 'Step 1: pull the image.', 'ana');
select add_version(1, 'Step 1: pull the image. Step 2: migrate.', 'bo');
select get_latest_content(1) as latest_content;
select * from get_document_versions(1);
select * from documents_by_author('ana');
select * from version_counts();

