CREATE TABLE Polls (
    poll_id            SERIAL PRIMARY KEY,
    poll_question      TEXT NOT NULL,
    created_by_user_id INTEGER NOT NULL,
    created_at         TIMESTAMP NOT NULL DEFAULT now(),
    is_active          BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Options (
    option_id   SERIAL PRIMARY KEY,
    poll_id     INTEGER NOT NULL REFERENCES Polls(poll_id),
    option_text TEXT NOT NULL
);

CREATE TABLE Votes (
    vote_id       SERIAL PRIMARY KEY,
    option_id     INTEGER NOT NULL REFERENCES Options(option_id),
    voter_user_id INTEGER NOT NULL,
    voted_at      TIMESTAMP NOT NULL DEFAULT now()
);

INSERT INTO Polls (poll_question, created_by_user_id, is_active) VALUES
    ('Best database engine?', 7, true),
    ('Favourite deployment day?', 7, false),
    ('Tabs or spaces?', 12, true);

INSERT INTO Options (poll_id, option_text) VALUES
    (1, 'PostgreSQL'), (1, 'SQLite'), (1, 'MySQL'),
    (2, 'Friday'), (2, 'Monday'),
    (3, 'Tabs'), (3, 'Spaces');

CREATE FUNCTION option_vote_totals(p_poll_id INTEGER)
RETURNS TABLE (option_id INTEGER, option_text TEXT, total_votes BIGINT) AS $$
    SELECT o.option_id, o.option_text, count(v.vote_id)
    FROM Options o
    LEFT JOIN Votes v ON v.option_id = o.option_id
    WHERE o.poll_id = p_poll_id
    GROUP BY o.option_id, o.option_text
    ORDER BY count(v.vote_id) DESC, o.option_id;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION polls_by_user(p_user_id INTEGER)
RETURNS TABLE (poll_id INTEGER, poll_question TEXT, created_at TIMESTAMP, open_now BOOLEAN) AS $$
    SELECT p.poll_id, p.poll_question, p.created_at, p.is_active
    FROM Polls p
    WHERE p.created_by_user_id = p_user_id
    ORDER BY p.created_at DESC;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION cast_vote(p_option_id INTEGER, p_user_id INTEGER)
RETURNS INTEGER AS $$
DECLARE
    v_open BOOLEAN;
    v_id   INTEGER;
BEGIN
    SELECT p.is_active INTO v_open
    FROM Options o
    JOIN Polls p ON p.poll_id = o.poll_id
    WHERE o.option_id = p_option_id;

    IF v_open IS NULL THEN
        RAISE EXCEPTION 'Option % does not exist', p_option_id;
    ELSIF v_open = false THEN
        RAISE EXCEPTION 'Poll for option % is closed', p_option_id;
    END IF;

    IF EXISTS (
        SELECT 1 FROM Votes v
        JOIN Options o ON o.option_id = v.option_id
        WHERE v.voter_user_id = p_user_id
          AND o.poll_id = (SELECT poll_id FROM Options WHERE option_id = p_option_id)
    ) THEN
        RAISE EXCEPTION 'User % already voted in this poll', p_user_id;
    END IF;

    INSERT INTO Votes (option_id, voter_user_id)
    VALUES (p_option_id, p_user_id)
    RETURNING vote_id INTO v_id;

    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION active_polls()
RETURNS TABLE (poll_id INTEGER, poll_question TEXT, created_by_user_id INTEGER) AS $$
    SELECT p.poll_id, p.poll_question, p.created_by_user_id
    FROM Polls p
    WHERE p.is_active = true
    ORDER BY p.created_at;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION votes_per_user()
RETURNS TABLE (voter_user_id INTEGER, total_votes BIGINT) AS $$
    SELECT v.voter_user_id, count(*)
    FROM Votes v
    GROUP BY v.voter_user_id
    ORDER BY count(*) DESC, v.voter_user_id;
$$ LANGUAGE sql STABLE;

SELECT cast_vote(1, 101);
SELECT cast_vote(1, 102);
SELECT cast_vote(2, 103);
SELECT cast_vote(6, 101);

UPDATE Polls SET is_active = false WHERE poll_id = 3;

SELECT * FROM option_vote_totals(1);
SELECT * FROM polls_by_user(7);
SELECT * FROM active_polls();
SELECT * FROM votes_per_user();
SELECT poll_question FROM Polls WHERE created_by_user_id = 12 AND is_active = false;

