INSERT INTO Achievements (achievement_id, achievement_name, description, points_awarded) VALUES
    (10, 'First Blood',  'Win your first match',      50),
    (11, 'Marathon',     'Play for 24 hours total',   150),
    (12, 'Beta Pioneer', 'Played during closed beta', 0),
    (13, 'Collector',    'Own every cosmetic item',   300);

INSERT INTO PlayerAchievements (player_id, achievement_id, date_achieved) VALUES
    (1, 10, DATE '2023-02-01'),
    (1, 11, DATE '2023-06-20'),
    (2, 10, DATE '2023-05-11'),
    (3, 12, DATE '2022-12-05');

-- 1. All achievements earned by a specific player.
CREATE FUNCTION player_achievements(p_player_id integer, p_scoring_only boolean DEFAULT false)
RETURNS TABLE (achievement_name text, points_awarded integer, date_achieved date)
LANGUAGE sql AS $$
    SELECT a.achievement_name, a.points_awarded, pa.date_achieved
    FROM PlayerAchievements pa
    JOIN Achievements a USING (achievement_id)
    WHERE pa.player_id = p_player_id
      AND (p_scoring_only = false OR a.points_awarded > 0)
    ORDER BY pa.date_achieved;
$$;

-- 2. All players who have earned a particular achievement.
CREATE FUNCTION achievement_earners(p_achievement_id integer, p_after_join_only boolean DEFAULT false)
RETURNS TABLE (player_name text, date_achieved date)
LANGUAGE sql AS $$
    SELECT p.player_name, pa.date_achieved
    FROM PlayerAchievements pa
    JOIN Players p USING (player_id)
    WHERE pa.achievement_id = p_achievement_id
      AND (p_after_join_only = false OR pa.date_achieved >= p.join_date)
    ORDER BY pa.date_achieved;
$$;

-- 3. Record a new achievement for a player.
CREATE FUNCTION grant_achievement(p_player_id integer, p_achievement_id integer, p_date date)
RETURNS boolean
LANGUAGE plpgsql AS $$
DECLARE
    v_recorded boolean := false;
BEGIN
    IF EXISTS (SELECT 1 FROM Players WHERE player_id = p_player_id)
       AND EXISTS (SELECT 1 FROM Achievements WHERE achievement_id = p_achievement_id) THEN
        INSERT INTO PlayerAchievements (player_id, achievement_id, date_achieved)
        VALUES (p_player_id, p_achievement_id, p_date)
        ON CONFLICT DO NOTHING;
        v_recorded := FOUND;
    END IF;
    INSERT INTO GrantLog (player_id, achievement_id, attempted_on, succeeded)
    VALUES (p_player_id, p_achievement_id, p_date, v_recorded);
    RETURN v_recorded;
END;
$$;

-- 4. Total points awarded to each player.
CREATE VIEW player_points AS
SELECT p.player_id,
       p.player_name,
       COALESCE(SUM(a.points_awarded), 0) AS total_points
FROM Players p
LEFT JOIN PlayerAchievements pa ON pa.player_id = p.player_id
LEFT JOIN Achievements a USING (achievement_id)
GROUP BY p.player_id, p.player_name;

-- 5. Achievements that have not been earned by any player.
CREATE VIEW unearned_achievements AS
SELECT a.achievement_id, a.achievement_name, a.points_awarded
FROM Achievements a
WHERE NOT EXISTS (SELECT 1 FROM PlayerAchievements pa WHERE pa.achievement_id = a.achievement_id);

CREATE VIEW rejected_grants AS
SELECT g.player_id, g.achievement_id, g.attempted_on
FROM GrantLog g
WHERE g.succeeded = false;

SELECT * FROM player_achievements(1);
SELECT * FROM player_achievements(3, true);
SELECT * FROM achievement_earners(10, true);
SELECT grant_achievement(2, 13, DATE '2024-03-09') AS collector_recorded,
       grant_achievement(2, 10, DATE '2024-03-09') AS duplicate_rejected,
       grant_achievement(9, 13, DATE '2024-03-09') AS unknown_player_rejected;
SELECT * FROM player_points ORDER BY total_points DESC;
SELECT * FROM unearned_achievements;
SELECT * FROM rejected_grants;

