CREATE TABLE Employees (
    employee_id integer PRIMARY KEY,
    employee_name text NOT NULL,
    manager_id integer REFERENCES Employees(employee_id),
    is_active boolean NOT NULL DEFAULT true
);
CREATE TABLE TimeOffTypes (
    type_id integer PRIMARY KEY,
    type_name text NOT NULL,
    requires_approval boolean NOT NULL
);
CREATE TABLE TimeOffRequests (
    request_id serial PRIMARY KEY,
    employee_id integer NOT NULL REFERENCES Employees(employee_id),
    type_id integer NOT NULL REFERENCES TimeOffTypes(type_id),
    start_date date NOT NULL,
    end_date date NOT NULL,
    status text NOT NULL,
    approved_by_manager_id integer REFERENCES Employees(employee_id),
    is_cancelled boolean NOT NULL DEFAULT false,
    CHECK (end_date >= start_date)
);
INSERT INTO Employees (employee_id, employee_name, manager_id, is_active) VALUES
    (1, 'Dana Reyes', NULL, true),
    (2, 'Ivan Petrov', 1, true),
    (3, 'Mara Lind', 1, true),
    (4, 'Owen Blake', 2, false);
INSERT INTO TimeOffTypes (type_id, type_name, requires_approval) VALUES
    (1, 'Vacation', true),
    (2, 'Sick Leave', false),
    (3, 'Unpaid Leave', true);
CREATE FUNCTION list_pending_requests(p_employee_id integer)
RETURNS TABLE (request_id integer, type_name text, start_date date, end_date date) AS $$
    SELECT r.request_id, t.type_name, r.start_date, r.end_date
      FROM TimeOffRequests r JOIN TimeOffTypes t ON t.type_id = r.type_id
     WHERE r.employee_id = p_employee_id AND r.status = 'PENDING'
       AND r.is_cancelled = false
     ORDER BY r.start_date;
$$ LANGUAGE sql;
CREATE FUNCTION requests_awaiting_manager(p_manager_id integer)
RETURNS TABLE (request_id integer, employee_name text, type_name text, days integer) AS $$
    SELECT r.request_id, e.employee_name, t.type_name,
           (r.end_date - r.start_date + 1) AS days
      FROM TimeOffRequests r JOIN Employees e ON e.employee_id = r.employee_id
      JOIN TimeOffTypes t ON t.type_id = r.type_id
     WHERE e.manager_id = p_manager_id AND t.requires_approval = true
       AND r.status = 'PENDING' AND r.is_cancelled = false
     ORDER BY r.start_date;
$$ LANGUAGE sql;
CREATE FUNCTION submit_request(p_employee_id integer, p_type_id integer,
                               p_start date, p_end date)
RETURNS integer AS $$
DECLARE v_needs_approval boolean; v_new_id integer;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Employees
                    WHERE employee_id = p_employee_id AND is_active = true) THEN
        RAISE EXCEPTION 'employee % is not active', p_employee_id;
    END IF;
    SELECT requires_approval INTO v_needs_approval
      FROM TimeOffTypes WHERE type_id = p_type_id;
    INSERT INTO TimeOffRequests (employee_id, type_id, start_date, end_date,
                                 status, approved_by_manager_id, is_cancelled)
    VALUES (p_employee_id, p_type_id, p_start, p_end,
            CASE WHEN v_needs_approval THEN 'PENDING' ELSE 'APPROVED' END,
            NULL, false)
    RETURNING request_id INTO v_new_id;
    RETURN v_new_id;
END;
$$ LANGUAGE plpgsql;
CREATE FUNCTION approve_request(p_request_id integer, p_manager_id integer)
RETURNS boolean AS $$
BEGIN
    UPDATE TimeOffRequests r
       SET status = 'APPROVED', approved_by_manager_id = p_manager_id
      FROM Employees e
     WHERE r.request_id = p_request_id AND e.employee_id = r.employee_id
       AND e.manager_id = p_manager_id AND r.status = 'PENDING'
       AND r.is_cancelled = false;
    RETURN FOUND;
END;
$$ LANGUAGE plpgsql;
CREATE FUNCTION cancel_request(p_request_id integer)
RETURNS boolean AS $$
BEGIN
    UPDATE TimeOffRequests SET is_cancelled = true, status = 'CANCELLED'
     WHERE request_id = p_request_id AND is_cancelled = false;
    RETURN FOUND;
END;
$$ LANGUAGE plpgsql;
CREATE FUNCTION days_by_type()
RETURNS TABLE (type_name text, requires_approval boolean, total_days bigint) AS $$
    SELECT t.type_name, t.requires_approval,
           COALESCE(SUM(r.end_date - r.start_date + 1), 0)::bigint
      FROM TimeOffTypes t
      LEFT JOIN TimeOffRequests r
             ON r.type_id = t.type_id AND r.is_cancelled = false
     GROUP BY t.type_name, t.requires_approval ORDER BY t.type_name;
$$ LANGUAGE sql;
SELECT submit_request(2, 1, DATE '2026-07-01', DATE '2026-07-10');
SELECT submit_request(2, 2, DATE '2026-03-04', DATE '2026-03-05');
SELECT submit_request(3, 3, DATE '2026-09-14', DATE '2026-09-18');
SELECT * FROM list_pending_requests(2);
SELECT approve_request(request_id, 1) FROM requests_awaiting_manager(1);
SELECT cancel_request(request_id) FROM list_pending_requests(3);
SELECT * FROM days_by_type();

