    FROM Tickets t
    JOIN Concerts c ON c.concert_id = t.concert_id
    WHERE t.customer_id = p_customer_id
      AND t.is_refunded = false
    ORDER BY c.concert_date;
END$$

CREATE PROCEDURE get_concert_customers(IN p_concert_id INT)
BEGIN
    SELECT DISTINCT cu.customer_id, cu.name, cu.email
    FROM Customers cu
    JOIN Tickets t ON t.customer_id = cu.customer_id
    WHERE t.concert_id = p_concert_id
      AND t.is_refunded = false
    ORDER BY cu.name;
END$$

CREATE PROCEDURE record_ticket_purchase(IN p_concert_id INT, IN p_customer_id INT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Concerts WHERE concert_id = p_concert_id AND is_cancelled = false) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Concert unavailable';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Customers WHERE customer_id = p_customer_id AND is_active = true) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Customer not active';
