CREATE TABLE Books (
    book_id INT PRIMARY KEY,
    title VARCHAR(200) NOT NULL,
    author VARCHAR(120) NOT NULL,
    genre VARCHAR(60) NOT NULL,
    total_copies INT NOT NULL,
    available_copies INT NOT NULL,
    is_lendable BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Borrowers (
    borrower_id INT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    email VARCHAR(120) NOT NULL,
    membership_active BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Loans (
    loan_id INT PRIMARY KEY AUTO_INCREMENT,
    book_id INT NOT NULL,
    borrower_id INT NOT NULL,
    loan_date DATETIME NOT NULL,
    due_date DATETIME NOT NULL,
    return_date DATETIME NULL,
    returned BOOLEAN NOT NULL DEFAULT false,
    FOREIGN KEY (book_id) REFERENCES Books(book_id),
    FOREIGN KEY (borrower_id) REFERENCES Borrowers(borrower_id)
);

INSERT INTO Books (book_id, title, author, genre, total_copies, available_copies, is_lendable) VALUES
    (1, 'Dune', 'Frank Herbert', 'Science Fiction', 4, 3, true),
    (2, 'The Hobbit', 'J.R.R. Tolkien', 'Fantasy', 2, 2, true),
