    (10, 'Ada Lovelace', 'ada@example.com', true),
    (11, 'Charles Babbage', 'charles@example.com', false);

CREATE VIEW vw_overdue_loans AS
SELECT l.loan_id, b.title, p.name, p.email, l.due_date,
       DATEDIFF(NOW(), l.due_date) AS days_overdue
FROM Loans l
JOIN Books b ON b.book_id = l.book_id
JOIN Borrowers p ON p.borrower_id = l.borrower_id
WHERE l.returned = false AND l.due_date < NOW();

DELIMITER $$

CREATE PROCEDURE sp_books_on_loan(IN p_borrower_id INT)
BEGIN
    SELECT b.book_id, b.title, b.author, l.loan_date, l.due_date
    FROM Loans l
    JOIN Books b ON b.book_id = l.book_id
    WHERE l.borrower_id = p_borrower_id AND l.returned = false
    ORDER BY l.due_date;
END$$

CREATE PROCEDURE sp_record_loan(IN p_book_id INT, IN p_borrower_id INT, IN p_days INT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Borrowers
                   WHERE borrower_id = p_borrower_id AND membership_active = true) THEN
        SIGNAL SQLSTATE '45001' SET MESSAGE_TEXT = 'Borrower membership is not active';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Books
                   WHERE book_id = p_book_id AND is_lendable = true AND available_copies > 0) THEN
        SIGNAL SQLSTATE '45002' SET MESSAGE_TEXT = 'Book is not available for loan';
    END IF;
    INSERT INTO Loans (book_id, borrower_id, loan_date, due_date, return_date, returned)
    VALUES (p_book_id, p_borrower_id, NOW(), DATE_ADD(NOW(), INTERVAL p_days DAY), NULL, false);
    UPDATE Books SET available_copies = available_copies - 1 WHERE book_id = p_book_id;
END$$

CREATE PROCEDURE sp_return_book(IN p_loan_id INT)
BEGIN
    UPDATE Loans SET returned = true, return_date = NOW()
    WHERE loan_id = p_loan_id AND returned = false;
    IF ROW_COUNT() = 0 THEN
        SIGNAL SQLSTATE '45003' SET MESSAGE_TEXT = 'Loan not found or already returned';
    END IF;
    UPDATE Books b
    JOIN Loans l ON l.book_id = b.book_id
    SET b.available_copies = LEAST(b.available_copies + 1, b.total_copies)
    WHERE l.loan_id = p_loan_id;
END$$

CREATE PROCEDURE sp_loans_per_genre()
BEGIN
    SELECT b.genre,
           COUNT(*) AS total_loans,
           SUM(l.returned = false) AS open_loans
    FROM Loans l
    JOIN Books b ON b.book_id = l.book_id
    GROUP BY b.genre
    ORDER BY total_loans DESC;
END$$

DELIMITER ;

CALL sp_record_loan(1, 10, 14);
CALL sp_record_loan(2, 10, 7);
CALL sp_books_on_loan(10);
UPDATE Loans SET due_date = DATE_SUB(NOW(), INTERVAL 3 DAY)
WHERE book_id = 2 AND returned = false;
SELECT * FROM vw_overdue_loans;
CALL sp_return_book((SELECT loan_id FROM Loans WHERE book_id = 1 AND returned = false));
CALL sp_loans_per_genre();

