CREATE FUNCTION interactions_for_contact(p_contact_id INT)
RETURNS TABLE (interaction_id INT, interaction_type VARCHAR, interaction_date TIMESTAMP, notes TEXT) AS $$
    SELECT i.interaction_id, i.interaction_type, i.interaction_date, i.notes
    FROM Interactions i
    WHERE i.contact_id = p_contact_id
    ORDER BY i.interaction_date DESC;
$$ LANGUAGE sql;

CREATE FUNCTION contacts_at_company(p_company VARCHAR)
RETURNS TABLE (contact_id INT, full_name TEXT, email VARCHAR, phone VARCHAR) AS $$
    SELECT c.contact_id, c.first_name || ' ' || c.last_name, c.email, c.phone
    FROM Contacts c
    WHERE c.company = p_company
      AND c.is_active = true
    ORDER BY c.last_name, c.first_name;
$$ LANGUAGE sql;

CREATE FUNCTION add_interaction(p_contact_id INT, p_type VARCHAR, p_notes TEXT, p_follow_up BOOLEAN)
RETURNS INT AS $$
DECLARE
    v_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Contacts WHERE contact_id = p_contact_id AND is_active = true) THEN
        RAISE EXCEPTION 'contact % is unknown or inactive', p_contact_id;
    END IF;
    SELECT COALESCE(MAX(interaction_id), 0) + 1 INTO v_id FROM Interactions;
    INSERT INTO Interactions (interaction_id, contact_id, interaction_type, interaction_date, notes, follow_up_required)
    VALUES (v_id, p_contact_id, p_type, CURRENT_TIMESTAMP, p_notes, p_follow_up);
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION update_contact_phone(p_contact_id INT, p_phone VARCHAR)
RETURNS BOOLEAN AS $$
DECLARE
    v_rows INT;
BEGIN
    UPDATE Contacts SET phone = p_phone
    WHERE contact_id = p_contact_id
      AND is_active = true;
