ALTER TABLE Users   ADD COLUMN is_active  boolean NOT NULL DEFAULT true;
ALTER TABLE Threads ADD COLUMN is_locked  boolean NOT NULL DEFAULT false;
ALTER TABLE Posts   ADD COLUMN is_deleted boolean NOT NULL DEFAULT false;

-- 1. All visible posts of one thread, oldest first, with the author's name.
CREATE FUNCTION thread_posts(p_thread_id integer)
RETURNS TABLE (post_id integer, username text, post_content text, post_date timestamp)
LANGUAGE sql STABLE AS $$
    SELECT p.post_id, u.username, p.post_content, p.post_date
    FROM Posts p
    JOIN Users u ON u.user_id = p.user_id
    WHERE p.thread_id = p_thread_id
      AND p.is_deleted = false
    ORDER BY p.post_date;
$$;

-- 2. Threads opened by one user.
CREATE FUNCTION user_threads(p_user_id integer)
RETURNS TABLE (thread_id integer, title text, category text, creation_date timestamp, is_locked boolean)
LANGUAGE sql STABLE AS $$
    SELECT t.thread_id, t.title, t.category, t.creation_date, t.is_locked
    FROM Threads t
    WHERE t.user_id = p_user_id
    ORDER BY t.creation_date DESC;
$$;

-- 3. Number of live posts per active user.
CREATE FUNCTION post_counts()
RETURNS TABLE (user_id integer, username text, post_count bigint)
LANGUAGE sql STABLE AS $$
    SELECT u.user_id, u.username, count(p.post_id)
    FROM Users u
    LEFT JOIN Posts p ON p.user_id = u.user_id AND p.is_deleted = false
    WHERE u.is_active = true
    GROUP BY u.user_id, u.username
    ORDER BY count(p.post_id) DESC, u.username;
$$;

-- 4. Append a post to an open thread, on behalf of an active user.
CREATE FUNCTION add_post(p_thread_id integer, p_user_id integer, p_content text)
RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE v_post_id integer;
BEGIN
    INSERT INTO Posts (thread_id, user_id, post_content, post_date, is_deleted)
    SELECT t.thread_id, u.user_id, p_content, now(), false
    FROM Threads t
    JOIN Users u ON u.user_id = p_user_id
    WHERE t.thread_id = p_thread_id
      AND t.is_locked = false
      AND u.is_active = true
    RETURNING post_id INTO v_post_id;

    IF v_post_id IS NULL THEN
        RAISE EXCEPTION 'thread % is locked or user % is inactive', p_thread_id, p_user_id;
    END IF;
    RETURN v_post_id;
END;
$$;

-- 5. Rename a thread (locked threads keep their title).
CREATE FUNCTION rename_thread(p_thread_id integer, p_title text)
RETURNS boolean
LANGUAGE plpgsql AS $$
DECLARE v_found boolean := false;
BEGIN
    UPDATE Threads SET title = p_title
    WHERE thread_id = p_thread_id
      AND is_locked = false
    RETURNING true INTO v_found;
    RETURN coalesce(v_found, false);
END;
$$;

DO $$
DECLARE v_new_post integer;
BEGIN
    INSERT INTO Users (username, email, join_date, is_active)
    VALUES ('ada', 'ada@example.com', current_date, true);
    INSERT INTO Threads (user_id, title, creation_date, category, is_locked)
    SELECT user_id, 'Indexing strategies', now(), 'databases', false
    FROM Users WHERE username = 'ada';

    v_new_post := add_post(
        (SELECT thread_id FROM Threads WHERE title = 'Indexing strategies'),
        (SELECT user_id FROM Users WHERE username = 'ada'),
        'Start with the query plan.');
    RAISE NOTICE 'post % created, rename ok: %', v_new_post,
        rename_thread((SELECT thread_id FROM Posts WHERE post_id = v_new_post),
                      'Indexing strategies (2026)');

    PERFORM * FROM thread_posts((SELECT thread_id FROM Posts WHERE post_id = v_new_post));
    PERFORM * FROM user_threads((SELECT user_id FROM Users WHERE username = 'ada'));
    PERFORM * FROM post_counts();
END;
$$;

