    (3, 11, DATE '2022-03-08', 'Treasurer', false);

CREATE FUNCTION club_roster(p_club_id integer)
RETURNS TABLE (student_id integer, full_name text, major text, role text) AS $$
    SELECT s.student_id, s.first_name || ' ' || s.last_name, s.major, m.role
    FROM Memberships m
    JOIN Students s ON s.student_id = m.student_id
    WHERE m.club_id = p_club_id
      AND m.is_active = true
      AND s.is_enrolled = true
    ORDER BY s.last_name;
$$ LANGUAGE sql;

CREATE FUNCTION student_clubs(p_student_id integer)
RETURNS TABLE (club_id integer, club_name text, role text, join_date date) AS $$
    SELECT c.club_id, c.club_name, m.role, m.join_date
    FROM Memberships m
    JOIN Clubs c ON c.club_id = m.club_id
    WHERE m.student_id = p_student_id
      AND m.is_active = true
      AND c.is_active = true
    ORDER BY m.join_date;
$$ LANGUAGE sql;

CREATE FUNCTION club_member_counts()
RETURNS TABLE (club_name text, member_count bigint) AS $$
    SELECT c.club_name, count(m.membership_id)
    FROM Clubs c
    LEFT JOIN Memberships m ON m.club_id = c.club_id AND m.is_active = true
    WHERE c.is_active = true
    GROUP BY c.club_name
    ORDER BY 2 DESC, 1;
$$ LANGUAGE sql;

CREATE FUNCTION add_member(p_student_id integer, p_club_id integer, p_role text DEFAULT 'Member')
RETURNS integer AS $$
DECLARE v_id integer;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Students WHERE student_id = p_student_id AND is_enrolled = true) THEN
        RAISE EXCEPTION 'Student % is not enrolled', p_student_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Clubs WHERE club_id = p_club_id AND is_active = true) THEN
        RAISE EXCEPTION 'Club % is not active', p_club_id;
    END IF;
    INSERT INTO Memberships (student_id, club_id, role, is_active)
    VALUES (p_student_id, p_club_id, p_role, true)
    ON CONFLICT (student_id, club_id)
    DO UPDATE SET is_active = true, role = p_role, join_date = CURRENT_DATE
    RETURNING membership_id INTO v_id;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION set_member_role(p_student_id integer, p_club_id integer, p_role text)
RETURNS boolean AS $$
BEGIN
    UPDATE Memberships SET role = p_role
    WHERE student_id = p_student_id
      AND club_id = p_club_id
      AND is_active = true;
    RETURN FOUND;
END;
$$ LANGUAGE plpgsql;

