-- Boolean flags the scheduling logic needs: retired venues and cancelled events
-- must not take part in capacity planning.
ALTER TABLE Venues ADD COLUMN is_active boolean NOT NULL DEFAULT true;
ALTER TABLE Events ADD COLUMN is_cancelled boolean NOT NULL DEFAULT false;

-- 1. All (live) events at a given venue, ordered by date.
CREATE OR REPLACE FUNCTION events_at_venue(p_venue_id integer)
RETURNS TABLE (event_id integer, event_name text, event_date date, estimated_attendees integer)
LANGUAGE sql AS $$
    SELECT e.event_id, e.event_name, e.event_date, e.estimated_attendees
    FROM Events e
    WHERE e.venue_id = p_venue_id
      AND e.is_cancelled = false
    ORDER BY e.event_date;
$$;

-- 2. Venues where a single event is expected to fill more than 80% of capacity.
CREATE OR REPLACE FUNCTION venues_over_80_percent()
RETURNS TABLE (venue_id integer, venue_name text, max_capacity integer,
               event_name text, estimated_attendees integer)
LANGUAGE sql AS $$
    SELECT v.venue_id, v.venue_name, v.max_capacity, e.event_name, e.estimated_attendees
    FROM Venues v
    JOIN Events e ON e.venue_id = v.venue_id
    WHERE v.is_active = true
      AND e.is_cancelled = false
      AND e.estimated_attendees > 0.8 * v.max_capacity
    ORDER BY e.estimated_attendees::numeric / v.max_capacity DESC;
$$;

-- 3. Total estimated attendees per venue (active venues, cancellations excluded).
CREATE OR REPLACE FUNCTION venue_attendance_totals()
RETURNS TABLE (venue_id integer, venue_name text, total_estimated_attendees bigint)
LANGUAGE sql AS $$
    SELECT v.venue_id, v.venue_name,
           COALESCE(SUM(e.estimated_attendees) FILTER (WHERE e.is_cancelled = false), 0)
    FROM Venues v
    LEFT JOIN Events e ON e.venue_id = v.venue_id
    WHERE v.is_active = true
    GROUP BY v.venue_id, v.venue_name
    ORDER BY 3 DESC;
$$;

-- 4. Schedule a new event, refusing retired venues and over-capacity bookings.
CREATE OR REPLACE FUNCTION schedule_event(p_event_name text, p_venue_id integer,
                                          p_event_date date, p_estimated integer)
RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
    v_capacity integer;
    v_new_id integer;
BEGIN
    SELECT max_capacity INTO v_capacity
    FROM Venues
    WHERE venue_id = p_venue_id
      AND is_active = true;

    IF v_capacity IS NULL THEN
        RAISE EXCEPTION 'Venue % is unknown or no longer active', p_venue_id;
    ELSIF p_estimated > v_capacity THEN
        RAISE EXCEPTION 'Estimate % exceeds capacity % of venue %', p_estimated, v_capacity, p_venue_id;
    END IF;

    INSERT INTO Events (event_name, venue_id, event_date, estimated_attendees, is_cancelled)
    VALUES (p_event_name, p_venue_id, p_event_date, p_estimated, false)
    RETURNING event_id INTO v_new_id;

    RETURN v_new_id;
END;
$$;

-- 5. Revise the estimate for an event that is still going ahead.
CREATE OR REPLACE FUNCTION update_estimated_attendees(p_event_id integer, p_estimated integer)
RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
    v_updated integer;
BEGIN
    UPDATE Events e
    SET estimated_attendees = p_estimated
    WHERE e.event_id = p_event_id
      AND e.is_cancelled = false
      AND p_estimated <= (SELECT v.max_capacity FROM Venues v WHERE v.venue_id = e.venue_id);

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated = 0 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;

-- Driver: book a gala, revise its estimate, then report on capacity pressure.
INSERT INTO Venues (venue_id, venue_name, address, max_capacity, is_active)
VALUES (1, 'Riverside Hall', '12 Quay Street', 500, true),
       (2, 'Old Foundry', '4 Mill Lane', 220, false);

SELECT schedule_event('Autumn Gala', 1, DATE '2026-10-03', 380);
SELECT update_estimated_attendees(e.event_id, 460)
FROM Events e
WHERE e.event_name = 'Autumn Gala';

SELECT * FROM events_at_venue(1);
SELECT * FROM venues_over_80_percent();
SELECT * FROM venue_attendance_totals();

