-- Blog schema with publication / visibility flags used by the queries below.
CREATE TABLE Authors (
    author_id  INT PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    email      VARCHAR(200) NOT NULL UNIQUE,
    is_active  BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Categories (
    category_id INT PRIMARY KEY,
    name        VARCHAR(100) NOT NULL UNIQUE,
    is_visible  BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Posts (
    post_id      INT PRIMARY KEY,
    author_id    INT NOT NULL REFERENCES Authors(author_id),
    category_id  INT NOT NULL REFERENCES Categories(category_id),
    title        VARCHAR(200) NOT NULL,
    content      TEXT,
    publish_date DATE,
    is_published BOOLEAN NOT NULL DEFAULT false
);

INSERT INTO Authors (author_id, name, email, is_active) VALUES
    (1, 'Ada Lovelace',  'ada@example.com',  true),
    (2, 'Grace Hopper',  'grace@example.com', true),
    (3, 'Retired Ghost', 'ghost@example.com', false);

INSERT INTO Categories (category_id, name, is_visible) VALUES
    (10, 'Technology', true),
    (20, 'Travel',     true),
    (30, 'Drafts Bin', false);

INSERT INTO Posts (post_id, author_id, category_id, title, content, publish_date, is_published) VALUES
    (100, 1, 10, 'Analytical Engines', 'Notes on mechanical computing.', DATE '2024-02-01', true),
    (101, 1, 20, 'Turin by Train',     'A slow ride through the Alps.',  DATE '2024-03-11', true),
    (102, 1, 10, 'Unfinished Essay',   'TODO: expand section two.',      NULL,             false),
    (103, 2, 10, 'Compilers at Sea',   'How A-0 came to be.',            DATE '2024-04-02', true);

-- 1. List all blog posts by a specific author.
CREATE FUNCTION posts_by_author(p_author_id INT)
RETURNS TABLE (post_id INT, title VARCHAR, publish_date DATE) AS $$
    SELECT p.post_id, p.title, p.publish_date
    FROM Posts p
    JOIN Authors a ON a.author_id = p.author_id
    WHERE p.author_id = p_author_id
      AND a.is_active = true
    ORDER BY p.publish_date DESC NULLS LAST;
$$ LANGUAGE sql;

-- 2. Find all posts in the 'Technology' category.
CREATE FUNCTION technology_posts()
RETURNS TABLE (post_id INT, title VARCHAR, author_name VARCHAR) AS $$
    SELECT p.post_id, p.title, a.name
    FROM Posts p
    JOIN Categories c ON c.category_id = p.category_id
    JOIN Authors a ON a.author_id = p.author_id
    WHERE c.name = 'Technology'
      AND c.is_visible = true
      AND p.is_published = true
    ORDER BY p.publish_date DESC;
$$ LANGUAGE sql;

-- 3. Count the number of posts per category.
CREATE FUNCTION post_counts_per_category()
RETURNS TABLE (category_name VARCHAR, published_posts BIGINT, draft_posts BIGINT) AS $$
    SELECT c.name,
           COUNT(*) FILTER (WHERE p.is_published = true),
           COUNT(*) FILTER (WHERE p.is_published = false)
    FROM Categories c
    LEFT JOIN Posts p ON p.category_id = c.category_id
    GROUP BY c.name
    ORDER BY c.name;
$$ LANGUAGE sql;

-- 4. Create a new blog post (rejects inactive authors and hidden categories).
CREATE FUNCTION create_post(p_author_id INT, p_category_id INT, p_title VARCHAR,
                            p_content TEXT, p_publish BOOLEAN)
RETURNS INT AS $$
DECLARE v_post_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Authors WHERE author_id = p_author_id AND is_active = true) THEN
        RAISE EXCEPTION 'author % may not publish', p_author_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Categories WHERE category_id = p_category_id AND is_visible = true) THEN
        RAISE EXCEPTION 'category % is hidden', p_category_id;
    END IF;
    SELECT COALESCE(MAX(post_id), 0) + 1 INTO v_post_id FROM Posts;
    INSERT INTO Posts (post_id, author_id, category_id, title, content, publish_date, is_published)
    VALUES (v_post_id, p_author_id, p_category_id, p_title, p_content,
            CASE WHEN p_publish = true THEN CURRENT_DATE ELSE NULL END, p_publish);
    RETURN v_post_id;
END;
$$ LANGUAGE plpgsql;

-- 5. Update the content of an existing post, optionally unpublishing it again.
CREATE FUNCTION update_post_content(p_post_id INT, p_content TEXT, p_keep_published BOOLEAN)
RETURNS BOOLEAN AS $$
DECLARE v_rows INT;
BEGIN
    UPDATE Posts
    SET content = p_content,
        is_published = p_keep_published,
        publish_date = CASE WHEN p_keep_published = false THEN NULL
                            ELSE COALESCE(publish_date, CURRENT_DATE) END
    WHERE post_id = p_post_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$ LANGUAGE plpgsql;

