VALUES (10, 'Single-cell Atlas', 'NIH', 450000, '2024-01-01', '2026-12-31', false),
       (11, 'Legacy Sequencing', 'NIH', 120000, '2018-01-01', '2020-12-31', true),
       (12, 'Methods Workshop', 'NSF', 60000, '2025-03-01', '2026-02-28', false);

SELECT assign_researcher(1, 10, 'Principal Investigator', true);
SELECT assign_researcher(2, 10, 'Co-Investigator', false);
SELECT assign_researcher(2, 12, 'Principal Investigator', true);
SELECT update_assignment_role(2, 10, 'Principal Investigator');

